def _bambu_chip_of(unit: afcBambuAMS) -> _BambuBufferChip:
    """
    The buffer chip a unit's ``__init__`` registered for its bus.

    :param unit: a built unit
    :return _BambuBufferChip: the chip under the unit's buffer_chip_name
    """
    return unit.printer._bambu_buffer_chips[unit.buffer_chip_name]


def _lane_cmd_printer() -> BambuPrinter:
    """
    A printer holding two real Bambu units, Bambu_AMS_1 (lane12..lane15)
    and the HT Bambu_AMS_HT_1 (lane28), plus objects that must never be
    taken for one: the [AFC_BambuAMS_rfid] section (a name sharing the
    prefix) and a BoxTurtle holding lane1.

    :return BambuPrinter: the printer
    """
    printer = make_printer()
    make_bambu_unit("Bambu_AMS_1", printer=printer,
                    lanes=["lane12", "lane13", "lane14", "lane15"])
    make_bambu_unit("Bambu_AMS_HT_1", printer=printer, model="ht",
                    ams_index=4, lanes=["lane28"])
    make_spoolman_section(printer)
    turtle = FabricatedSection("AFC_BoxTurtle Turtle_1", {})
    turtle.lanes = {"lane1": object()}
    printer.add_object("AFC_BoxTurtle Turtle_1", turtle)
    return printer


def _lane_cmd_unit(printer: BambuPrinter, name: str) -> afcBambuAMS:
    """
    :param printer: a printer from _lane_cmd_printer
    :param name: a unit's name
    :return afcBambuAMS: that unit
    """
    return printer.lookup_object(f"AFC_BambuAMS {name}")


def _lane_cmd_register(unit: afcBambuAMS, cmd: str = "AFC_BAMBU_TESTCMD",
                       unit_alone: bool = False) -> Recorder:
    """
    Register ``cmd`` on ``unit`` with a recording handler.

    :param unit: the unit
    :param cmd: the command name
    :param unit_alone: the command runs with UNIT= and no LANE=
    :return Recorder: the handler, recording each gcmd it is given
    """
    handler = Recorder()
    _register_lane_command(unit, cmd, handler, desc="test",
                           unit_alone=unit_alone)
    return handler


def _lane_cmd_ran(handler: Recorder) -> List[Dict[str, Any]]:
    """
    :param handler: a handler from _lane_cmd_register
    :return list: the parameters of each command it ran, in order
    """
    return [args[0].get_command_parameters() for args, _kw in handler.calls]


def _bambu_faulted_unit(loads_ok: bool = True, paused: bool = True,
                        tool_loaded: bool = False
                        ) -> Tuple[afcBambuAMS, Any, List[str]]:
    """
    A unit whose fault emptied lane15, the print paused (or not), and the
    printer's CHANGE_TOOL loading the lane (or not).

    :param loads_ok: CHANGE_TOOL leaves the lane tool_loaded
    :param paused: the print is paused
    :param tool_loaded: lane15 is already at the toolhead
    :return tuple: (unit, lane15, scripts the unit ran)
    """
    printer = make_printer(print_state="paused" if paused else "printing")
    unit = make_bambu_unit(printer=printer,
                           lanes=["lane12", "lane13", "lane14", "lane15"])
    lane = unit.lanes["lane15"]
    lane.tool_loaded = tool_loaded
    unit._resume_needs_reload = True
    unit._auto_recover_armed = True
    unit._fault_lane = lane
    unit._auto_resume_count = 2
    scripts: List[str] = []

    def change_tool(script: str) -> None:
        """:param script: the script the unit ran"""
        scripts.append(script)
        if loads_ok:
            lane.tool_loaded = True

    unit.gcode.run_script_from_command = change_tool
    return unit, lane, scripts


class _HeldSpoolmanClient(FakeSpoolmanClient):
    """A Spoolman client that also records what it is asked."""

    def __init__(self, spools: Sequence[Dict[str, Any]] = ()) -> None:
        """:param spools: Spoolman's spool records"""
        super().__init__(spools)
        self.asked: List[tuple] = []

    def get_spool(self, spool_id: int) -> Optional[Dict[str, Any]]:
        """:return Optional[dict]: the spool, the call recorded"""
        self.asked.append(("get_spool", spool_id))
        return super().get_spool(spool_id)

    def search_spools(self) -> List[Dict[str, Any]]:
        """:return list: every spool, the call recorded"""
        self.asked.append(("search_spools",))
        return super().search_spools()


def _held_spool(spool_id: int, chips: str = "",
                tray: Optional[str] = None) -> Dict[str, Any]:
    """
    :param spool_id: the spool's id
    :param chips: the chip UIDs it records (card_uids), comma separated
    :param tray: the reel it records (tray_uid)
    :return dict: the spool as Spoolman returns it
    """
    extra = {}
    if chips:
        extra["card_uids"] = f'"{chips}"'
    if tray:
        extra["tray_uid"] = f'"{tray}"'
    return {"id": spool_id, "remaining_weight": 500.0, "extra": extra}


#: The UID the pool units in the held-record tests are claimed as.
_HELD_CLAIM_UID = "0123456789ABCDEF01234567"


def _held_claim(held: Optional[Dict[str, Dict[str, Any]]], *,
                bays: Sequence[Dict[str, Any]] = ({"present": True},),
                lanes: Sequence[str] = ("lane15",), name: str = "AMS",
                model: str = "boxed", spoolman: Optional[str] = None,
                client: Optional[_HeldSpoolmanClient] = None,
                monkeypatch: Optional[pytest.MonkeyPatch] = None,
                prep_seen: bool = False,
                printer: Optional[BambuPrinter] = None,
                disconnected: bool = False) -> afcBambuAMS:
    """
    A pool unit claimed with the records its master handed over (none
    handed when ``held`` is None), and its bays as the bridge reports them
    once it has polled the unit. Scan priming has not run.

    :param held: lane name -> saved record, for hold_lanes
    :param bays: bay records by bay (normalized keys; ``present`` defaults
      True)
    :param lanes: the unit's lanes, by bay
    :param name: the unit's name
    :param model: its model, configured and claimed as
    :param spoolman: AFC core's spoolman setting
    :param client: Spoolman as the [AFC_BambuAMS_rfid] module reaches it;
      with it the module is configured (needs ``monkeypatch``)
    :param monkeypatch: pytest's monkeypatch fixture
    :param prep_seen: PREP has walked the lanes (a reclaim)
    :param printer: the printer; a new one when None
    :param disconnected: the host disconnected (klippy:disconnect) after
      boot, and the bridge is back on its port (``printer`` built with
      monkeypatch)
    :return afcBambuAMS: the claimed unit
    """
    printer = printer or make_printer()
    bridge = FakeBridge(uids=[_HELD_CLAIM_UID])
    unit = make_bambu_unit(name, printer=printer, model=model, bridge=bridge,
                           lanes=list(lanes), values={"pool": True},
                           prep_seen=prep_seen)
    if disconnected:
        unit._handle_disconnect()
        assert unit._bridge is None and bridge.stopped is True
        bambu_mod._bridge_mod._BRIDGES[unit.serial_port] = bridge
    unit.afc.spoolman = spoolman
    if client is not None:
        assert monkeypatch is not None
        use_spoolman_client(monkeypatch, client)
        make_bambu_spoolman(unit, spoolman_url=spoolman)
    if held is not None:
        unit.hold_lanes(held)
    assert unit.claim(_HELD_CLAIM_UID, model)
    assert unit.logger.messages == [
        ("debug", f"AFC bambu {name}: chain index not resolved yet (UID "
                  f"{_HELD_CLAIM_UID}); holding this unit's registrations "
                  f"until the chain map arrives"),
        ("info", f"AFC bambu {name}: claimed UID {_HELD_CLAIM_UID} as "
                 f"{model} and brought online live (ams_index=0).")]
    unit.logger.messages.clear()
    for i, bay in enumerate(bays):
        rec = dict(bay)
        info = slot_info(i, present=rec.pop("present", True))
        info.update(rec)
        unit._slots[i] = info
        unit._prev_present[i] = bool(info["present"])
        unit._auto_scanned[i] = True
    unit._presence_ok = True            # the bridge has polled the unit
    return unit


#: The UID the pool units in the held-record tests are claimed as.
_P2_HELD_UID = "0123456789ABCDEF01234567"


#: Spoolman's address on AFC core, for the units whose lanes it links.
_P2_SPOOLMAN_URL = "http://spoolman:7912"


#: The READY box a claim's PREP block draws for a four-bay unit; the unit's
#: name follows it.
_P2_LOGO4 = ("<span class=success--text>R  +---------------+\n"
             "E  |    BambuAMS   |\nA  +---+---+---+---+\n"
             "D  | O | O | O | O |\nY  +---+---+---+---+</span>\n   ")


#: What PREP shows for a bay while the bridge has not reported the unit.
_P2_OFFLINE = ("<span class=warning--text>(AMS offline, bridge protocol "
               "bring-up)</span>")


def _p2_held_claim(monkeypatch: pytest.MonkeyPatch,
                   held: Optional[Dict[str, Dict[str, Any]]], *,
                   bays: Sequence[Dict[str, Any]] = ({"present": True},),
                   lanes: Sequence[str] = ("lane15",),
                   spoolman: Optional[str] = None,
                   client: Optional[FakeSpoolmanClient] = None,
                   spool: Optional[FakeAfcSpool] = None) -> afcBambuAMS:
    """
    The pool unit "AMS" claimed as a boxed AMS with the records its master
    handed over (none handed when ``held`` is None), and its bays as the
    bridge reports them once it has polled the unit. Scan priming has not
    run; the claim's own lines are checked and cleared.

    :param monkeypatch: pytest's monkeypatch fixture
    :param held: lane name -> saved record, for hold_lanes
    :param bays: bay records by bay: ``present`` (default True) and the
      wire keys ``material``, ``color``, ``uid``, ``tray_uid`` go through
      the real slot normalization, any other key is set as given
    :param lanes: the unit's lanes, by bay
    :param spoolman: AFC core's spoolman setting
    :param client: Spoolman as the [AFC_BambuAMS_rfid] module reaches it;
      with it the section is configured and its jobs run inline
    :param spool: AFC core's spool object; FakeAfcSpool when None
    :return afcBambuAMS: the claimed unit
    """
    printer = make_printer(monkeypatch=monkeypatch)
    unit = make_bambu_unit("AMS", printer=printer, model="boxed",
                           bridge=FakeBridge(uids=[_P2_HELD_UID]),
                           lanes=list(lanes), values={"pool": True})
    unit.afc.spoolman = spoolman
    if spool is not None:
        unit.afc.spool = spool
    if client is not None:
        use_spoolman_client(monkeypatch, client)
        make_bambu_spoolman(unit, spoolman_url=spoolman)
    if held is not None:
        unit.hold_lanes(held)
    assert unit.claim(_P2_HELD_UID, "boxed") is True
    assert unit.logger.messages == [
        ("debug", f"AFC bambu AMS: chain index not resolved yet (UID "
                  f"{_P2_HELD_UID}); holding this unit's registrations "
                  f"until the chain map arrives"),
        ("info", f"AFC bambu AMS: claimed UID {_P2_HELD_UID} as boxed and "
                 f"brought online live (ams_index=0).")]
    unit.logger.messages.clear()
    wire_keys = ("material", "color", "uid", "tray_uid")
    for i, bay in enumerate(bays):
        rec = dict(bay)
        present = rec.pop("present", True)
        wire = {k: rec.pop(k) for k in wire_keys if k in rec}
        info = slot_info(i, present=present, **wire)
        info.update(rec)
        unit._slots[i] = info
        unit._prev_present[i] = bool(present)
        unit._auto_scanned[i] = True
    unit._presence_ok = True            # the bridge has polled the unit
    return unit


def _p2_held_prep(*shown: Tuple[str, Optional[str]],
                  empty: Sequence[str] = ()) -> List[LogLine]:
    """
    The PREP block a live claim of "AMS" prints at priming.

    :param shown: (lane, what its line shows in brackets, None for nothing)
      for the lanes with a spool, by bay
    :param empty: the lanes of empty bays, after them
    :return list: the log lines
    """
    lines: List[LogLine] = [("info", "BambuAMS AMS Prepping lanes")]
    for lane, what in shown:
        bracket = f" ({what})" if what is not None else ""
        lines.append(("info", (
            f"{lane} tool cmd: NONE <span class=success--text>LOCKED AND "
            f"LOADED</span>{bracket} {_P2_OFFLINE}")))
    for lane in empty:
        lines.append(("info", f"{lane} tool cmd: NONE EMPTY READY FOR SPOOL "
                              f"{_P2_OFFLINE}"))
    lines.append(("raw", f"{_P2_LOGO4}AMS\n"))
    return lines


