def _p2_keeps(tag: str) -> LogLine:
    """
    :param tag: the tag's material
    :return LogLine: the line for lane15's record kept by its bay's tag
    """
    return ("debug", f"AFC bambu AMS: lane15 keeps its saved record: the tag "
                     f"in bay 1 ({tag}) is the same spool")


def _p2_applied(tag: str, colour: str, uid: str, bed: str = "?C (unknown)",
                summary: bool = True, lane: str = "lane15",
                unit: str = "AMS") -> List[LogLine]:
    """
    :param tag: the tag's material
    :param colour: its colour, "" for none
    :param uid: its chip UID as the readout shows it
    :param bed: the readout's bed temperature and where it came from
    :param summary: the tag's readout follows (once per tag)
    :param lane: the lane it was applied to
    :param unit: the unit's name
    :return list: the lines of the tag applied to the lane as a read
    """
    shown = f" #{colour}" if colour else ""
    lines: List[LogLine] = [
        ("info", f"AFC bambu {unit}: applied tag to {lane}: Bambu "
                 f"{tag}{shown}")]
    if summary:
        lines.append((
            "debug", f"AFC bambu {unit}: {lane} tag -- {tag} | color "
                     f"{'#' + colour if colour else '?'} | uid {uid} | "
                     f"remaining no measurement yet | nominal 1000 g | "
                     f"nozzle ?-?C | bed {bed}"))
    return lines


def _p2_dropped(tag: str, why: str, sid: Optional[int] = None) -> LogLine:
    """
    :param tag: the tag in bay 1, material and colour as the line shows them
    :param why: the reason in brackets
    :param sid: the link the record lost, if any
    :return LogLine: the line for lane15's record replaced by its bay's tag
    """
    link = f" and its link to spool {sid}" if sid is not None else ""
    return ("info", f"AFC bambu AMS: lane15 -- the tag in bay 1 ({tag}) is "
                    f"not the spool saved for this lane ({why}); the tag "
                    f"replaces the saved record{link}")


def _p2_chain_unit(monkeypatch: pytest.MonkeyPatch, uid: Optional[str],
                   chain: Sequence[str] = (), *, model: str = "ams1",
                   ams_index: int = 0, resolved: bool = False,
                   bridge: Optional[FakeBridge] = None,
                   offline: bool = False) -> afcBambuAMS:
    """
    The unit "AMS" with ``unit_uid`` set, on a bridge whose chain map is
    ``chain``; its construction's sends and lines are cleared.

    :param monkeypatch: pytest's monkeypatch fixture
    :param uid: its unit_uid, None for none configured
    :param chain: chain index -> unit UID, as the bridge reports it
    :param model: its ams_model
    :param ams_index: its configured chain index
    :param resolved: the index is already confirmed by the UID
    :param bridge: its bridge; a FakeBridge with ``chain`` when None
    :param offline: it has no bridge
    :return afcBambuAMS: the unit
    """
    printer = make_printer(monkeypatch=monkeypatch)
    unit = make_bambu_unit(
        "AMS", printer=printer, model=model, ams_index=ams_index,
        values={"unit_uid": uid} if uid else {}, id_resolved=resolved,
        bridge=bridge if bridge is not None else FakeBridge(uids=chain),
        offline=offline)
    unit.logger.messages.clear()
    if unit._bridge is not None:
        unit._bridge.sent.clear()
    return unit


def _p2_registers(index: int, *, units: bool = True, status: bool = False,
                  model: int = 0) -> List[Dict[str, Any]]:
    """
    :param index: the boxed unit's chain index
    :param units: the polled-unit count leads
    :param status: a status request follows
    :param model: the firmware's model number
    :return list: what an AMS 1 sends to register itself at ``index``
    """
    frames: List[Dict[str, Any]] = []
    if units:
        frames.append({"cmd": "units", "n": index + 1})
    frames += [{"cmd": "htunit", "unit": index, "on": 0},
               {"cmd": "capen", "unit": index, "on": 0},
               {"cmd": "model", "unit": index, "m": model},
               {"cmd": "mcaddr", "unit": index, "addr": 0x0700, "pay": index}]
    if status:
        frames.append({"cmd": "status"})
    return frames


