def _p2_flap_feed(unit: afcBambuAMS, frame: Dict[str, Any],
                  dt: float = 0.24, times: int = 1) -> None:
    """
    Status frames ``dt`` seconds apart, each followed by the reactor's due
    callbacks (a Spoolman answer and a reconnect's settle land on them).

    :param unit: the unit
    :param frame: the raw frame
    :param dt: seconds since the last frame
    :param times: how many
    """
    for _ in range(times):
        unit.reactor.now += dt
        unit._on_status(frame)
        unit.reactor.run_callbacks()


def _p2_flap_unit(monkeypatch: pytest.MonkeyPatch, *,
                  scanned: Sequence[int] = (),
                  stamp: Tuple[int, int] = (0, 0), ht: bool = False,
                  client: Optional[FakeSpoolmanClient] = None,
                  toolhead: bool = False,
                  values: Optional[Dict[str, Any]] = None,
                  inline: bool = True,
                  virtual_hub: bool = True) -> afcBambuAMS:
    """
    Printer 1's lane15 mid-print: bound to spool 136 (PLA Basic #0086D6,
    670 g), its bay occupied, PREP run and primed, the bay claimed by AFC.
    Spoolman is the real delegate over :func:`_p2_flap_spoolman`; AFC
    core's spool object binds at once. The setup lines are cleared.

    :param monkeypatch: pytest's monkeypatch fixture
    :param scanned: bays scanned on this connection
    :param stamp: (meas_seq, meas_pct) the bay's record carries
    :param ht: an AMS HT, lane15 in its one bay, instead of an AMS 1 with
      lane15 in bay 4
    :param client: Spoolman; _p2_flap_spoolman() when None
    :param toolhead: lane12 is on bay 1, loaded to the toolhead
    :param values: further config options
    :param inline: the delegate's Spoolman jobs run on the calling thread
    :param virtual_hub: the unit's hub has no switch of its own
    :return afcBambuAMS: "Bambu_AMS_1"
    """
    printer = make_printer(now=126000.0, monkeypatch=monkeypatch,
                           print_state="printing")
    slot = 0 if ht else 3
    lanes = [LaneSpec(
        "lane15", slot, prep=True, loaded_to_hub=True, material="PLA",
        color="#0086D6", spool_id=136, weight=670,
        extras={"sub_type": "Basic", "spool_vendor": "Bambu",
                "filament_name": "Bambu PLA Basic", "extruder_temp": 190.0,
                "bed_temp": 55.0, "bambu_sku": "GFA00"})]
    if toolhead:
        lanes.insert(0, LaneSpec("lane12", 0, prep=True, load=True,
                                 loaded_to_hub=True, tool_loaded=True,
                                 material="PLA", spool_id=150))
    unit = make_bambu_unit(printer=printer, model="ht" if ht else "ams1",
                           bridge=_P2FlapBridge(), lanes=lanes, values=values,
                           virtual_hub=virtual_hub)
    use_spoolman_client(monkeypatch, client if client is not None
                        else _p2_flap_spoolman())
    make_bambu_spoolman(unit, spoolman_url=_P2_SPOOLMAN_URL, inline=inline)
    unit.afc.spool = _P2BindingSpool()
    unit._scanned_bays = set(scanned)
    seq, pct = stamp
    session = _p2_flap_frame(True, ht=ht, mseq=seq, mpct=pct)
    _p2_flap_feed(unit, session)                   # the baseline frame
    unit._prep_seen = True
    unit._afc_owned.add(slot)                      # PREP: the lane has data
    unit._scan_primed = True
    _p2_flap_feed(unit, session, dt=1.0, times=3)
    unit.logger.messages.clear()
    return unit


def _p2_flap_removed(slot: int = 3) -> LogLine:
    """:return LogLine: the removal of a bay's spool"""
    return ("info", f"{_P2_FLAP}: spool REMOVED from slot {slot} (AMS bay "
                    f"{slot + 1})")


def _p2_flap_inserted(slot: int = 3) -> LogLine:
    """:return LogLine: an insert into a bay"""
    return ("info", f"{_P2_FLAP}: spool INSERTED in slot {slot} (AMS bay "
                    f"{slot + 1})")


def _p2_flap_unbinding(spool_id: int = 136) -> LogLine:
    """:return LogLine: lane15 unbound because its bay is empty"""
    return ("debug", f"{_P2_FLAP}: unbinding lane15 from spool {spool_id} -- "
                     f"the bay is empty")


def _p2_flap_relinked(remaining: str = "no measurement yet") -> List[LogLine]:
    """
    :param remaining: what the tag readout says of the measurement
    :return list: lane15's tag applied again from its record and linked to
      spool 136 by its reel
    """
    return [
        ("info", f"{_P2_FLAP}: applied tag to lane15: Bambu PLA Basic "
                 f"#0086D6"),
        ("debug", f"{_P2_FLAP}: lane15 tag -- PLA Basic GFA00 | color #0086D6 "
                  f"| uid 95F2C30C | remaining {remaining} | nominal 1000 g | "
                  f"nozzle 190-230C | bed 55C (material)"),
        ("debug", f"{_P2_FLAP}: matched lane15 to Spoolman spool 136 by tray "
                  f"UID {_P2_TRAY15}")]


def _p2_flap_reconnect_cmds(ht: bool = False) -> List[str]:
    """
    :param ht: the unit is an HT
    :return list: the commands a reconnect and its settle send: two info
      requests, the announce, and a status request
    """
    ht0f = ["ht0fhold"] if ht else []
    return (["info", "info", "units", "htunit"] + ht0f
            + ["capen", "model", "mcaddr", "armms", "status"])


def _p2_engage(slot: int) -> List[Dict[str, Any]]:
    """
    :param slot: the tray's bay, 0-based, on the unit at chain index 0
    :return list: what engaging the follower sends: the mode-07 finish (three
      raw frames), select (mode:4) and assist, in that order
    """
    return [{"cmd": "raw", "hex": "3DC50CC803000900A502800C"},
            {"cmd": "raw", "hex": "3DC50CC8030007000002514C"},
            {"cmd": "raw", "hex": "3DC50CC8030007007F023654"},
            {"cmd": "select", "unit": 0, "slot": slot},
            {"cmd": "assist", "unit": 0, "slot": slot, "on": True}]


def _p2_follow_unit(monkeypatch: pytest.MonkeyPatch, *,
                    names: Sequence[str] = ("lane13", "lane14", "lane15",
                                            "lane16"),
                    loaded: Optional[str] = "lane15",
                    tool_loaded: bool = True, now: float = 100.0,
                    **kwargs: Any) -> afcBambuAMS:
    """
    An AMS 2 "AMS" whose lanes are ``names`` by bay, AFC's extruder
    recording ``loaded`` as its lane; sends and lines cleared.

    :param monkeypatch: pytest's monkeypatch fixture
    :param names: the unit's lanes, by bay
    :param loaded: the lane AFC's extruder records loaded, if any
    :param tool_loaded: that lane, when it is the unit's, is tool-loaded
    :param now: the printer's clock
    :param kwargs: further make_bambu_unit arguments
    :return afcBambuAMS: the unit
    """
    printer = make_printer(monkeypatch=monkeypatch, now=now)
    lanes = [LaneSpec(n, i, prep=True, load=True, loaded_to_hub=True,
                      tool_loaded=tool_loaded) if n == loaded else n
             for i, n in enumerate(names)]
    unit = make_bambu_unit("AMS", printer=printer, lanes=lanes,
                           slots=[slot_info(i) for i in range(len(names))],
                           **kwargs)
    unit.afc.tools["extruder"].lane_loaded = loaded
    unit.logger.messages.clear()
    if unit._bridge is not None:
        unit._bridge.sent.clear()
    return unit


