#: The chip UID of the PLA Basic reel in bay 1 of the measuring unit.
_P3_UID = "d13fdb0e"


def _bambu_p3_fails(*_args: Any, **_kwargs: Any) -> Any:
    """
    A collaborator call that fails.

    :raises RuntimeError: always
    """
    raise RuntimeError("collaborator failed")


def _bambu_p3_measuring_unit(
        monkeypatch: pytest.MonkeyPatch, *, section: Optional[bool] = None,
        client: Optional[FakeSpoolmanClient] = None,
        spoolman_url: Optional[str] = None, lane: str = "lane8",
        spool_id: Optional[int] = None, weight: float = 999.0,
        material: str = "PLA Basic", lane_material: Optional[str] = None,
        record: Optional[Dict[str, Any]] = None,
        **kwargs: Any) -> afcBambuAMS:
    """
    A real unit "Bambu_AMS_1" whose bay 1 holds a tagged 1 kg reel (tag
    d13fdb0e, 80% on its tag), mapped to one lane, with no bridge left to
    ask about a scan. Bay 0 is empty and bays 2 and 3 have never reported.

    :param monkeypatch: pytest's monkeypatch fixture
    :param section: True registers an enabled [AFC_BambuAMS_rfid]; None
      leaves the unit with its measurement-only delegate
    :param client: the Spoolman client the delegate reaches; an empty one
      when None
    :param spoolman_url: AFC core's Spoolman setting
    :param lane: bay 1's lane
    :param spool_id: the lane's Spoolman binding
    :param weight: the lane's grams
    :param material: the bay record's material, which picks the density
    :param lane_material: the lane's material; the record's base when None
      (a PLA lane is sub_type Basic)
    :param record: bay 1's record; the tagged reel when None
    :param kwargs: further make_bambu_unit arguments
    :return afcBambuAMS: the unit; ``unit._measure`` is its delegate
    """
    printer = make_printer(monkeypatch=monkeypatch)
    use_spoolman_client(monkeypatch, client if client is not None
                        else FakeSpoolmanClient())
    if record is None:
        record = slot_info(1, material=material or None, uid=_P3_UID,
                           weight=1000, remain=80)
    if lane_material is None:
        lane_material = material.split()[0] if material else ""
    sub_type = "Basic" if lane_material == "PLA" else ""
    kwargs.setdefault("offline", True)
    unit = make_bambu_unit(
        printer=printer,
        lanes=[LaneSpec(lane, 1, weight=weight, material=lane_material,
                        spool_id=spool_id, extras={"sub_type": sub_type})],
        slots=[slot_info(0, present=False), record], **kwargs)
    make_bambu_spoolman(unit, section=bool(section),
                        spoolman_url=spoolman_url)
    return unit


class _P4SwitchBridge(FakeBridge):
    """A FakeBridge that also reports the bays' narrated switch states."""

    def __init__(self, **kwargs: Any) -> None:
        """:param kwargs: FakeBridge's arguments"""
        super().__init__(**kwargs)
        #: (device address, chain index, bay) -> (switch state, when)
        self.switches: Dict[Tuple[int, int, int], Tuple[int, float]] = {}

    def tray_switches(self, addr: Optional[int], unit: Optional[int],
                      slot: int) -> Optional[Tuple[int, float]]:
        """
        As BambuBridge.tray_switches: bit 0 the inlet, bit 1 the outlet.

        :param addr: device address of the unit
        :param unit: the unit's chain index
        :param slot: 0-based bay index
        :return tuple: (switch state, reactor time), or None if never narrated
        """
        if not addr or unit is None:
            return None
        return self.switches.get((int(addr), int(unit), int(slot)))


