def _p4_printing_unit(monkeypatch: pytest.MonkeyPatch, lane: str, *,
                      printing: bool = True, loaded: bool = True,
                      online: bool = True, preslen: int = 4,
                      bridge: Optional[FakeBridge] = None) -> afcBambuAMS:
    """
    A unit whose bay 2 lane is printing, every bay full, scans primed, for
    the presence runout. Bays 0 and 1 hold lane4 and lane5.

    :param monkeypatch: pytest's monkeypatch fixture
    :param lane: bay 2's lane
    :param printing: print_stats reads printing
    :param loaded: that lane is loaded to its extruder
    :param online: the unit reports online
    :param preslen: the unit's last presence reply length (0 = none yet)
    :param bridge: the unit's bridge; a FakeBridge when None
    :return afcBambuAMS: the unit
    """
    bridge = bridge if bridge is not None else FakeBridge()
    bridge.status = {"units": [{"n": 0, "online": online,
                                "preslen": preslen}]}
    return _p4_unit(
        monkeypatch, print_state="printing" if printing else "standby",
        bridge=bridge, scan_primed=True,
        lanes=[LaneSpec("lane4", 0), LaneSpec("lane5", 1),
               LaneSpec(lane, 2, tool_loaded=loaded)],
        slots=[slot_info(i) for i in range(4)])


def _p4_readout(remaining: str, *, lane: str = "lane12", head: str = "ABS",
                colour: str = "?", uid: str = "C32A080A", nominal: int = 1000,
                nozzle: str = "?-?", bed: str = "?",
                source: str = "unknown") -> LogLine:
    """
    The DEBUG readout line _log_tag_readout writes for a tag.

    :param remaining: the remaining field's text
    :param lane: the lane named
    :param head: material, then SKU
    :param colour: the colour field
    :param uid: the chip UID as printed
    :param nominal: the reel's nominal grams
    :param nozzle: the nozzle range
    :param bed: the bed temperature
    :param source: where the bed temperature came from
    :return tuple: the readout line
    """
    return ("debug", f"AFC bambu Bambu_AMS_1: {lane} tag -- {head} | "
                     f"color {colour} | uid {uid} | remaining {remaining} "
                     f"| nominal {nominal} g | nozzle {nozzle}C | bed "
                     f"{bed}C ({source})")


#: Printer 1's lane15 reel: its chip UID and its roll identity.
_P4_UID15 = "95f2c30c"


_P4_TRAY15 = "4e3177c31fea42d08bc240c818a37f80"


def _p4_lane15_unit(monkeypatch: pytest.MonkeyPatch, *,
                    pool: bool = False,
                    lane: Optional[LaneSpec] = None) -> afcBambuAMS:
    """
    A unit holding lane15 on bay 3 as a restart left it: restored PLA Basic
    in #0086D6, no spool; the bay's record carries the reel's UID and roll.
    PREP has run and the prime fired; AFC core has Spoolman.

    :param monkeypatch: pytest's monkeypatch fixture
    :param pool: build it as an unclaimed pool spare
    :param lane: lane15's spec; the restored one when None
    :return afcBambuAMS: the unit
    """
    lane = lane or LaneSpec("lane15", 3, material="PLA", color="#0086D6",
                            weight=1000, extras={"sub_type": "Basic"})
    unit = _p4_unit(monkeypatch, lanes=[lane], prep_seen=True,
                    scan_primed=True, values={"pool": pool},
                    slots=[slot_info(0, present=False),
                           slot_info(1, present=False),
                           slot_info(2, present=False),
                           slot_info(3, material="PLA Basic", color="0086D6",
                                     uid=_P4_UID15, tray_uid=_P4_TRAY15,
                                     sku="GFA00", weight=1000)])
    unit.afc.spoolman = "http://spoolman:7912"
    return unit


def _p4_spoolman136(monkeypatch: pytest.MonkeyPatch) -> List[Tuple[str, str]]:
    """
    Printer 1's Spoolman as the tag lookup sees it: spool 136 by its roll.

    :param monkeypatch: pytest's monkeypatch fixture
    :return list: every (uid, tray_uid) it is asked about
    """
    use_spoolman_client(monkeypatch, FakeSpoolmanClient())
    asked: List[Tuple[str, str]] = []

    def _match(client: Any, uid: str,
               tray_uid: str = "") -> Tuple[Optional[dict], bool, None]:
        """
        :param client: the Spoolman client
        :param uid: the chip UID asked about
        :param tray_uid: the roll identity asked about
        :return tuple: (spool, matched by roll, error)
        """
        asked.append((uid, tray_uid))
        if tray_uid == _P4_TRAY15:
            return {"id": 136, "remaining_weight": 670.8}, True, None
        return None, False, None

    monkeypatch.setattr(AFC_BambuAMS_rfid, "match_spool_for_tag", _match)
    return asked


def _p4_chamber(temp: float = 52.0, target: float = 55.0,
                seen: float = 100.0) -> Dict[str, Any]:
    """
    One unit's [AMS_CHMB] drying record, as the bridge keeps it.

    :param temp: chamber temperature
    :param target: the cycle's target
    :param seen: when it was last narrated (reactor time)
    :return dict: the record
    """
    return {"temp": temp, "target": target, "state": 2, "seen": seen}


