#: AFC core's Spoolman, for the units whose lanes a bind can reach.
_P5_SPOOLMAN_URL = "http://spoolman:7912"


def _bambu_p5_measuring_unit(
        monkeypatch: pytest.MonkeyPatch, *, section: Optional[bool] = None,
        client: Optional[FakeSpoolmanClient] = None,
        spoolman_url: Optional[str] = None, pool: bool = False,
        lane: str = "lane8", spool_id: Optional[int] = None,
        weight: float = 999.0, lane_material: str = "PLA",
        record: Optional[Dict[str, Any]] = None,
        **kwargs: Any) -> afcBambuAMS:
    """
    A real unit whose bay 1 holds a tagged 1 kg PLA Basic reel (tag says 80%
    left), mapped to one lane.

    :param monkeypatch: pytest's monkeypatch fixture
    :param section: True registers an enabled [AFC_BambuAMS_rfid] section;
      None leaves the unit with its measurement-only delegate
    :param client: the Spoolman client the delegate reaches; an empty one
      when None
    :param spoolman_url: AFC core's Spoolman setting
    :param pool: build the unit as an unclaimed pool spare
    :param lane: bay 1's lane
    :param spool_id: the lane's Spoolman binding
    :param weight: the lane's grams
    :param lane_material: the lane's material; PLA lanes are sub_type Basic
    :param record: bay 1's slot record; the tagged reel when None
    :param kwargs: further make_bambu_unit arguments
    :return afcBambuAMS: the unit
    """
    printer = make_printer(monkeypatch=monkeypatch)
    use_spoolman_client(monkeypatch, client or FakeSpoolmanClient())
    if record is None:
        record = slot_info(1, material="PLA Basic", uid="d13fdb0e",
                           weight=1000, remain=80)
    sub_type = "Basic" if lane_material == "PLA" else ""
    unit = make_bambu_unit(
        printer=printer, values={"pool": pool},
        lanes=[LaneSpec(lane, 1, weight=weight, material=lane_material,
                        spool_id=spool_id, extras={"sub_type": sub_type})],
        slots=[slot_info(0, present=False), record,
               slot_info(2, present=False), slot_info(3, present=False)],
        **kwargs)
    if spoolman_url is not None:
        unit.afc.spoolman = spoolman_url
    if section:
        make_bambu_spoolman(unit)
    return unit


#: What the one-edge verdict block says, for the unit "HT" and its bay 0.
_P5_RETRYING = ("AFC bambu HT: slot 0 one-edged its insert measurement "
                "(rst:0, no percent narrated) -- measure_on_insert is "
                "retrying it once")


_P5_ONE_PULL = ("AFC bambu HT: slot 0 finished its cycle but never narrated a "
                "percent (rst:0) -- it took only ONE pull, so there was no "
                "second edge to measure from. That is geometric and it "
                "follows the SPOOL, not the bay: the second edge needs a full "
                "revolution of filament past the reader, so a large or full "
                "reel can come up short. Running it again often lands it.")


def _bambu_p5_one_edged_unit(
        monkeypatch: pytest.MonkeyPatch, *, model: str = "ht",
        measure: bool = True, cali: Optional[Dict[str, Any]] = None,
        measured: Optional[Dict[str, Any]] = None, latched: bool = False,
        present: bool = True) -> afcBambuAMS:
    """
    The unit "HT" (chain index 4), whose bay 0 (lane23) opened its insert
    measurement window at 10.0 and whose calibration verdict landed at 50.0;
    the clock reads 60.0.

    :param monkeypatch: pytest's monkeypatch fixture
    :param model: ams_model
    :param measure: measure_on_insert
    :param cali: the verdict; rst:0 at 50.0 when None
    :param measured: the reading stored at the unit's address, if any
    :param latched: the one-shot retry already ran for this insert
    :param present: a spool is in bay 0
    :return afcBambuAMS: the unit
    """
    bridge = FakeBridge(cali={4: cali or {"rst": 0, "t": 50.0}})
    printer = make_printer(monkeypatch=monkeypatch, now=10.0)
    unit = make_bambu_unit("HT", printer=printer, model=model, ams_index=4,
                           bridge=bridge,
                           values={"measure_on_insert": measure},
                           lanes=[LaneSpec("lane23", 0)],
                           slots=[slot_info(0, present=present,
                                            material="PLA Basic",
                                            weight=1000)])
    if measured is not None:
        bridge.cap_by_addr[unit.dry_dev_addr] = measured
    unit._cap_open_pending(0)
    if latched:
        unit._auto_cali_slot = 0
    unit.reactor.now = 60.0
    return unit


def _bambu_p5_assist(on: bool, slot: int = 0, unit: int = 0) -> dict:
    """
    :param on: assist on or off
    :param slot: the bay
    :param unit: the chain index
    :return dict: the assist frame set_feed_assist sends
    """
    return {"cmd": "assist", "unit": unit, "slot": slot, "on": on}


