class TestBridgeSlotToInfo:
    #: The record bridge_slot_to_info makes of a slot that says nothing.
    BLANK = {
        "index": 0, "present": False, "state": "empty", "material": None,
        "sku": None, "color": None, "color_black": False, "temp_min": None,
        "temp_max": None, "weight": None, "bed_temp": None,
        "bed_temp_source": None, "remain_pct": None, "rfid_uid": None,
        "tray_uid": None, "scan_seq": None, "scan_res": None,
        "meas_pct": None, "meas_seq": None, "meas_radius_mm": None,
        "reread_pending": False, "hub_raw": None}

    @staticmethod
    def _tag(**fields: Any) -> Dict[str, Any]:
        """
        A slot as a read Bambu tag fills it (a PLA Basic, blue).

        :param fields: wire fields that replace the tag's own
        :return dict: the wire slot
        """
        base: Dict[str, Any] = {
            "i": 0, "present": True, "state": "idle", "material": "PLA Basic",
            "sku": "GFA00", "color": "0086D6FF", "tmin": 190, "tmax": 230,
            "weight": 1000, "remain": 60, "bedt": 0, "uid": "95f2c30c",
            "tray_uid": "4e" * 16}
        base.update(fields)
        return base

    def test_the_bridge_slot_map_carries_the_radius(self):
        info = bridge_slot_to_info({"i": 0, "mpct": 144, "mrad": 94})
        assert info == dict(self.BLANK, meas_pct=144, meas_radius_mm=94)
        # 0 is the firmware's "the line stated none", not a radius of zero.
        assert bridge_slot_to_info({"i": 0, "mrad": 0}) == self.BLANK

    def test_full_slot(self):
        info = bridge_slot_to_info({
            "i": 2, "present": True, "state": "idle", "material": "PLA",
            "sku": "GFA00", "color": "00ae42ff", "tmin": 220, "tmax": 240,
            "weight": 1000})
        # No 'bedt' at all: the figure comes from the material, labelled so.
        assert info == dict(
            self.BLANK, index=2, present=True, state="idle", material="PLA",
            sku="GFA00", color="00AE42", temp_min=220, temp_max=240,
            weight=1000, bed_temp=55, bed_temp_source="material")

    def test_every_measured_and_scan_field_is_carried(self):
        info = bridge_slot_to_info(self._tag(
            sseq=4, sres=1, mpct=87, mseq=9, mrad=61, rrq=1, remain=0))
        assert info == dict(
            self.BLANK, present=True, state="idle", material="PLA Basic",
            sku="GFA00", color="0086D6", temp_min=190, temp_max=230,
            weight=1000, bed_temp=55, bed_temp_source="material",
            remain_pct=0, rfid_uid="95f2c30c", tray_uid="4e" * 16,
            scan_seq=4, scan_res=1, meas_pct=87, meas_seq=9,
            meas_radius_mm=61, reread_pending=True)

    @pytest.mark.parametrize("raw, black, colour", [
        ("000000FF", True, None), ("00000000", False, None),
        ("2D2B28FF", False, "2D2B28"), (None, False, None)],
        ids=["black-tag", "no-colour", "colour", "absent"])
    def test_a_black_tag_is_told_from_no_colour(self, raw, black, colour):
        # The firmware forces a decoded colour's alpha to FF, and publishes
        # 00000000 for a record with none: both read as colour None.
        info = bridge_slot_to_info({"i": 0, "present": True, "color": raw})
        assert info == dict(self.BLANK, present=True, color=colour,
                            color_black=black)

    def test_no_uid_ever(self):
        # Bambu never exposes a per-spool UID in 'rfid'; only 'uid' is read.
        info = bridge_slot_to_info({"i": 0, "present": True, "rfid": "aabbcc"})
        assert info == dict(self.BLANK, present=True)

    def test_empty_slot(self):
        info = bridge_slot_to_info({
            "i": 0, "present": False, "state": "empty",
            "material": "", "sku": "", "color": "00000000",
            "tmin": 0, "tmax": 0, "remain": -1, "sseq": "x", "mpct": -1})
        assert info == self.BLANK

    def test_missing_fields_default(self):
        assert bridge_slot_to_info({"i": 1}) == dict(self.BLANK, index=1)

    def test_the_tag_bed_temperature_reaches_the_slot_info(self):
        # Most tags write 0 ("not stated"), which must not land as a 0 C bed.
        assert bridge_slot_to_info({"i": 0, "bedt": 35})["bed_temp"] == 35
        assert bridge_slot_to_info({"i": 0, "bedt": 0})["bed_temp"] is None
        assert bridge_slot_to_info({"i": 0})["bed_temp"] is None
        # Nothing a tag could plausibly mean by a bed temperature.
        assert bridge_slot_to_info({"i": 0, "bedt": 4000})["bed_temp"] is None
        assert bridge_slot_to_info({"i": 0, "bedt": -5})["bed_temp"] is None
        assert bridge_slot_to_info({"i": 0, "bedt": 200})["bed_temp"] == 200

    def test_the_hub_sensor_is_read_from_the_bridge_slot(self):
        assert bridge_slot_to_info({"i": 0, "present": True,
                                    "hubv": 0xE8})["hub_raw"] == 0xE8
        # 0 = the firmware has not read it; absent = a firmware before 2.83.
        assert bridge_slot_to_info({"i": 0, "hubv": 0})["hub_raw"] is None
        assert bridge_slot_to_info({"i": 0})["hub_raw"] is None

    def test_a_tag_that_states_a_bed_temperature_wins_and_says_so(self):
        out = bridge_slot_to_info(self._tag(bedt=35))
        assert (out["bed_temp"], out["bed_temp_source"]) == (35, "tag")

    def test_a_silent_tag_falls_back_to_the_material_and_says_so(self):
        pla = bridge_slot_to_info(self._tag(material="PLA Basic", bedt=0))
        assert (pla["bed_temp"], pla["bed_temp_source"]) == (55, "material")
        abs_ = bridge_slot_to_info(self._tag(material="ABS", bedt=0,
                                             tmin=240, tmax=270))
        assert (abs_["bed_temp"], abs_["bed_temp_source"]) == (90,
                                                               "material")

    def test_an_untagged_bay_claims_nothing(self):
        out = bridge_slot_to_info(self._tag(material=None, sku=None, bedt=0,
                                            uid=""))
        assert (out["bed_temp"], out["bed_temp_source"]) == (None, None)
        assert out["rfid_uid"] is None

    def test_a_zero_is_not_published_as_a_zero_degree_bed(self):
        out = bridge_slot_to_info(self._tag(material="PLA Basic", bedt=0))
        assert (out["bed_temp"], out["bed_temp_source"]) == (55, "material")
        # An out-of-range reading is refused the same way.
        for bad in (-5, 900):
            out = bridge_slot_to_info(self._tag(bedt=bad))
            assert (out["bed_temp"], out["bed_temp_source"]) == (55,
                                                                  "material")


class TestBuildSlotMap:
    @staticmethod
    def _lanes(*slots: Tuple[str, int]) -> Dict[str, Any]:
        """
        Real lanes on one printer, ``unit: U:<slot + 1>`` each.

        :param slots: (lane name, 0-based slot) pairs
        :return dict: lane name -> lane
        """
        printer = make_printer()
        return {name: make_afc_lane(name, "U", slot, printer=printer)
                for name, slot in slots}

    def test_maps_1based_to_0based(self):
        lanes = self._lanes(("a", 0), ("b", 3))
        assert build_slot_map(lanes, 4) == {"a": 0, "b": 3}

    def test_out_of_range_raises(self):
        with pytest.raises(ValueError) as exc:
            build_slot_map(self._lanes(("a", 4)), 4)
        assert str(exc.value) == (
            "lane 'a' has index 5, outside this unit's slots 1..4")

    def test_zero_index_raises(self):
        with pytest.raises(ValueError) as exc:
            build_slot_map(self._lanes(("a", -1)), 4)
        assert str(exc.value) == (
            "lane 'a' has index 0, outside this unit's slots 1..4")

    def test_duplicate_index_raises(self):
        with pytest.raises(ValueError) as exc:
            build_slot_map(self._lanes(("a", 1), ("b", 1)), 4)
        assert str(exc.value) == (
            "lanes 'a' and 'b' both map to slot 1 (index 2); each lane needs "
            "a unique index")


