class TestBambuBufferADCSetupAdcCallback:
    def test_push_klipper_and_kalico_signatures(self):
        got: List[float] = []
        adc = _BambuBufferADC(_bambu_chip_of(make_bambu_unit()))
        adc.setup_adc_callback(0.1, got.append)            # klipper (rt, cb)
        assert adc._callback == got.append
        adc.push(0.5)
        later: List[float] = []
        adc.setup_adc_callback(later.append)               # kalico (cb)
        assert adc._callback == later.append
        adc.push(0.9)
        assert (got, later) == ([0.5], [0.9])

    def test_push_with_no_consumer_delivers_nothing(self):
        adc = _BambuBufferADC(_bambu_chip_of(make_bambu_unit()))
        adc.push(0.5)
        # Nothing is buffered: a consumer added later sees only later pushes.
        got: List[float] = []
        adc.setup_adc_callback(0.1, got.append)
        adc.push(0.9)
        assert got == [0.9]


