class TestRegisterBambuBufferChip:
    class _Pins:
        """Klipper's pin registry, recording the chips registered on it."""

        def __init__(self) -> None:
            """Start with no chips."""
            self.chips: List[Tuple[str, Any]] = []

        def register_chip(self, name: str, chip: Any) -> None:
            """
            :param name: the chip name an adc_pin references
            :param chip: the chip
            """
            self.chips.append((name, chip))

    class _ScoutStub:
        """
        What AFC_BridgeBox._register_scout_chip registers a chip with: the
        printer, the chip name, no reading, and the scout_stub mark.
        """

        def __init__(self, printer: BambuPrinter, name: str) -> None:
            """
            :param printer: the printer
            :param name: the chip name
            """
            self.printer = printer
            self.buffer_chip_name = name
            self.scout_stub = True

        def fps_buffer_value(self) -> Optional[float]:
            """:return Optional[float]: None, a scout stub has no buffer"""
            return None

    @staticmethod
    def _printer() -> Tuple[BambuPrinter, "TestRegisterBambuBufferChip._Pins"]:
        """
        :return tuple: a printer and the pin registry its units register on
        """
        printer = make_printer()
        pins = TestRegisterBambuBufferChip._Pins()
        printer.add_object("pins", pins)
        return printer, pins

    @staticmethod
    def _scout_stub(printer: BambuPrinter, name: str) -> Any:
        """
        The unitless stub a bridge-only scout chain registers its chip with,
        as AFC_BridgeBox._register_scout_chip builds it.

        :param printer: the printer
        :param name: the chip name
        :return Any: the stub
        """
        return TestRegisterBambuBufferChip._ScoutStub(printer, name)

    def test_units_sharing_a_master_share_one_chip(self):
        printer, pins = self._printer()
        a = make_bambu_unit("Bambu_AMS_1", printer=printer)
        b = make_bambu_unit("Bambu_AMS_2", printer=printer, ams_index=1)
        chip = printer._bambu_buffer_chips["bambu_buffer"]
        assert list(printer._bambu_buffer_chips) == ["bambu_buffer"]
        assert pins.chips == [("bambu_buffer", chip)]
        assert chip._unit is a
        _register_bambu_buffer_chip(b)
        assert pins.chips == [("bambu_buffer", chip)] and chip._unit is a

    def test_a_second_master_gets_its_own_chip(self):
        printer, pins = self._printer()
        make_bambu_unit("Bambu_AMS_1", printer=printer)
        make_bambu_unit("Bambu_AMS_2", printer=printer,
                        values={"buffer_chip_name": "bambu_buffer_2",
                                "serial_port": "/dev/ttyB"})
        chips = printer._bambu_buffer_chips
        assert sorted(chips) == ["bambu_buffer", "bambu_buffer_2"]
        assert pins.chips == [("bambu_buffer", chips["bambu_buffer"]),
                              ("bambu_buffer_2", chips["bambu_buffer_2"])]

    def test_each_chip_reads_its_own_unit(self):
        # The failure this prevents: a second bus reporting the first's value.
        printer, _pins = self._printer()
        a = make_bambu_unit("Bambu_AMS_1", printer=printer,
                            bridge=FakeBridge(status={"buff": 20}))
        b = make_bambu_unit("Bambu_AMS_2", printer=printer,
                            values={"buffer_chip_name": "bambu_buffer_2",
                                    "serial_port": "/dev/ttyB"},
                            bridge=FakeBridge(status={"buff": 80}))
        chips = printer._bambu_buffer_chips
        assert (chips["bambu_buffer"]._unit, chips["bambu_buffer_2"]._unit) == (
            a, b)
        assert chips["bambu_buffer"]._unit.fps_buffer_value() == 0.2
        assert chips["bambu_buffer_2"]._unit.fps_buffer_value() == 0.8

    def test_the_scout_stub_chip_reads_the_first_unit_on_it(self):
        printer, pins = self._printer()
        stub = self._scout_stub(printer, "bambu_buffer")
        _register_bambu_buffer_chip(stub)
        chip = printer._bambu_buffer_chips["bambu_buffer"]
        assert chip._unit is stub
        # A second scout stub does not take it from the first.
        _register_bambu_buffer_chip(self._scout_stub(printer, "bambu_buffer"))
        assert chip._unit is stub
        unit = make_bambu_unit("Bambu_AMS_1", printer=printer)
        make_bambu_unit("Bambu_AMS_2", printer=printer, ams_index=1)
        assert printer._bambu_buffer_chips == {"bambu_buffer": chip}
        assert pins.chips == [("bambu_buffer", chip)]
        assert chip._unit is unit


class TestGcmdInt:
    @staticmethod
    def _gcmd(**params: Any) -> FakeGcmd:
        """
        :param params: the command's parameters, as typed
        :return FakeGcmd: a command whose get_int is Klipper's (decimal only)
        """
        line = " ".join(["AFC_BAMBU_HEATER_START"]
                        + [f"{k}={v}" for k, v in params.items()])
        return FakeGcmd(params, command="AFC_BAMBU_HEATER_START",
                        commandline=line)

    def test_a_missing_parameter_takes_the_default(self):
        assert _gcmd_int(self._gcmd(), "ADDR", 7, 0, 99) == 7

    def test_decimal_still_works(self):
        assert _gcmd_int(self._gcmd(ADDR="1792"), "ADDR", 0, 0, 0xFFFF) == 1792

    def test_hex_is_accepted(self):
        assert _gcmd_int(self._gcmd(ADDR="0x0700"), "ADDR", 0, 0,
                         0xFFFF) == 1792

    def test_hex_and_decimal_agree(self):
        hexed = _gcmd_int(self._gcmd(ADDR="0x1800"), "ADDR", 0, 0, 0xFFFF)
        dec = _gcmd_int(self._gcmd(ADDR="6144"), "ADDR", 0, 0, 0xFFFF)
        assert hexed == dec == 6144

    def test_surrounding_whitespace_is_tolerated(self):
        assert _gcmd_int(self._gcmd(P=" 0x80 "), "P", 255, 0, 255) == 128

    def test_garbage_is_an_error_not_a_default(self):
        # Falling back to the default would address another device.
        gcmd = self._gcmd(ADDR="nonsense")
        with pytest.raises(BambuPrinter.command_error) as exc:
            _gcmd_int(gcmd, "ADDR", 0, 0, 0xFFFF)
        assert str(exc.value) == (
            "Error on 'AFC_BAMBU_HEATER_START ADDR=nonsense': unable to "
            "parse nonsense")

    def test_out_of_range_is_refused(self):
        with pytest.raises(BambuPrinter.command_error) as exc:
            _gcmd_int(self._gcmd(P="0x1FF"), "P", 255, 0, 255)
        assert str(exc.value) == (
            "Error on 'AFC_BAMBU_HEATER_START P=0x1FF': P=0x1FF is outside "
            "0..255")
        with pytest.raises(BambuPrinter.command_error) as exc:
            _gcmd_int(self._gcmd(P="-0x1"), "P", 255, 0, 255)
        assert str(exc.value) == (
            "Error on 'AFC_BAMBU_HEATER_START P=-0x1': P=-0x1 is outside "
            "0..255")

    def test_the_bounds_are_inclusive(self):
        assert _gcmd_int(self._gcmd(P="0xFF"), "P", 0, 0, 255) == 255
        assert _gcmd_int(self._gcmd(P="0x0"), "P", 9, 0, 255) == 0
        assert _gcmd_int(self._gcmd(P="0"), "P", 9, 0, 255) == 0


class TestClampSpeed:
    def test_zero_uses_ceiling(self):
        assert clamp_speed(0, 30) == 30

    def test_negative_uses_ceiling(self):
        assert clamp_speed(-5, 30) == 30

    def test_above_ceiling_clamped(self):
        assert clamp_speed(100, 30) == 30

    def test_within_passes(self):
        assert clamp_speed(20, 30) == 20

    def test_an_explicit_speed_is_still_honoured_and_clamped(self):
        # feed()/retract() clamp to MAX_MMPS (30 mm/s), not a config value.
        assert clamp_speed(999.0, bambu_mod.MAX_MMPS) == 30.0
        assert clamp_speed(5.0, bambu_mod.MAX_MMPS) == 5.0


class TestRegisterLaneCommand:
    def test_unit_still_reaches_its_unit_with_or_without_a_lane(self):
        printer = _lane_cmd_printer()
        ams = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_1"))
        ht = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_HT_1"))
        printer.gcode.run("AFC_BAMBU_TESTCMD", UNIT="Bambu_AMS_1")
        printer.gcode.run("AFC_BAMBU_TESTCMD", UNIT="Bambu_AMS_HT_1",
                          LANE="lane28")
        assert _lane_cmd_ran(ams) == [{"UNIT": "Bambu_AMS_1"}]
        assert _lane_cmd_ran(ht) == [{"UNIT": "Bambu_AMS_HT_1",
                                      "LANE": "lane28"}]

    def test_a_unit_that_does_not_exist_is_still_refused(self):
        printer = _lane_cmd_printer()
        ams = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_1"))
        ht = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_HT_1"))
        with pytest.raises(BambuPrinter.command_error) as exc:
            printer.gcode.run("AFC_BAMBU_TESTCMD", UNIT="Bambu_AMS_9",
                              LANE="lane14")
        assert str(exc.value) == "The value 'Bambu_AMS_9' is not valid for UNIT"
        assert (ams.calls, ht.calls) == ([], [])

    def test_the_default_is_claimed_once_and_later_units_register_cleanly(
            self):
        printer = make_printer()
        units = [make_bambu_unit(f"Bambu_AMS_{i}", printer=printer,
                                 ams_index=i - 1,
                                 lanes=[f"lane{i}"]) for i in range(1, 5)]
        handlers = [_lane_cmd_register(u) for u in units]
        key, values = printer.gcode.mux_commands["AFC_BAMBU_TESTCMD"]
        assert key == "UNIT"
        assert sorted(v for v in values if v is not None) == [
            "Bambu_AMS_1", "Bambu_AMS_2", "Bambu_AMS_3", "Bambu_AMS_4"]
        assert None in values
        for unit, handler in zip(units, handlers):
            assert unit._lane_handlers["AFC_BAMBU_TESTCMD"] is handler
            assert values[unit.name] is handler

    def test_a_new_printer_in_the_same_process_gets_the_default_again(self):
        # Klipper's RESTART builds a new printer and g-code object in the
        # same process; nothing module-level may decide it is already done.
        for _ in range(2):
            printer = make_printer()
            unit = make_bambu_unit(printer=printer, lanes=["lane14"])
            handler = _lane_cmd_register(unit)
            printer.gcode.run("AFC_BAMBU_TESTCMD", LANE="lane14")
            assert _lane_cmd_ran(handler) == [{"LANE": "lane14"}]


class TestRunByLane:
    def test_lane_alone_runs_the_unit_that_holds_the_lane(self):
        printer = _lane_cmd_printer()
        ams = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_1"))
        ht = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_HT_1"))
        printer.gcode.run("AFC_BAMBU_TESTCMD", LANE="lane14")
        printer.gcode.run("AFC_BAMBU_TESTCMD", LANE="lane28")
        assert _lane_cmd_ran(ams) == [{"LANE": "lane14"}]
        assert _lane_cmd_ran(ht) == [{"LANE": "lane28"}]

    def test_a_lane_no_bambu_unit_holds_is_refused_naming_the_units(self):
        printer = _lane_cmd_printer()
        ams = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_1"))
        ht = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_HT_1"))
        for lane in ("lane99", "lane1"):          # unknown; on a BoxTurtle
            with pytest.raises(BambuPrinter.command_error) as exc:
                printer.gcode.run("AFC_BAMBU_TESTCMD", LANE=lane)
            assert str(exc.value) == (
                f"AFC_BAMBU_TESTCMD: no Bambu unit holds a lane named "
                f"'{lane}' (Bambu units: Bambu_AMS_1, Bambu_AMS_HT_1)")
        assert (ams.calls, ht.calls) == ([], [])

    def test_neither_lane_nor_unit_asks_for_the_lane(self):
        printer = _lane_cmd_printer()
        ams = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_1"))
        with pytest.raises(BambuPrinter.command_error) as exc:
            printer.gcode.run("AFC_BAMBU_TESTCMD")
        assert str(exc.value) == "AFC_BAMBU_TESTCMD: needs LANE= naming the lane"
        assert ams.calls == []

    def test_a_command_that_runs_on_a_whole_unit_offers_unit(self):
        printer = _lane_cmd_printer()
        ams = _lane_cmd_register(_lane_cmd_unit(printer, "Bambu_AMS_1"),
                                 unit_alone=True)
        with pytest.raises(BambuPrinter.command_error) as exc:
            printer.gcode.run("AFC_BAMBU_TESTCMD")
        # No angle brackets: Moonraker reports such an error as "Unknown".
        assert str(exc.value) == (
            "AFC_BAMBU_TESTCMD: needs LANE= (one lane) or UNIT= (every slot "
            "on that unit). Bambu units: Bambu_AMS_1")
        assert ams.calls == []

    def test_a_lane_released_to_the_pool_is_no_longer_found(self):
        # deactivate_to_pool takes the lane out of its unit's lanes.
        printer = _lane_cmd_printer()
        ht_unit = _lane_cmd_unit(printer, "Bambu_AMS_HT_1")
        ht = _lane_cmd_register(ht_unit)
        del ht_unit.lanes["lane28"]
        with pytest.raises(BambuPrinter.command_error) as exc:
            printer.gcode.run("AFC_BAMBU_TESTCMD", LANE="lane28")
        assert str(exc.value) == (
            "AFC_BAMBU_TESTCMD: no Bambu unit holds a lane named 'lane28' "
            "(Bambu units: Bambu_AMS_HT_1)")
        assert ht.calls == []

    def test_only_units_that_registered_the_command_are_candidates(self):
        # A unit holding the lane but without this command is not handed it.
        printer = make_printer()
        a = make_bambu_unit("Bambu_AMS_1", printer=printer, lanes=["lane12"])
        b = make_bambu_unit("Bambu_AMS_2", printer=printer, ams_index=1,
                            lanes=["lane16"])
        prime = _lane_cmd_register(a, "AFC_BAMBU_TESTPRIME")
        scan = _lane_cmd_register(b, "AFC_BAMBU_TESTSCAN")
        with pytest.raises(BambuPrinter.command_error) as exc:
            printer.gcode.run("AFC_BAMBU_TESTPRIME", LANE="lane16")
        assert str(exc.value) == (
            "AFC_BAMBU_TESTPRIME: no Bambu unit holds a lane named 'lane16' "
            "(Bambu units: Bambu_AMS_1)")
        printer.gcode.run("AFC_BAMBU_TESTPRIME", LANE="lane12")
        assert _lane_cmd_ran(prime) == [{"LANE": "lane12"}]
        assert scan.calls == []

    def test_run_by_lane_without_a_printer_refuses_instead_of_crashing(self):
        gcmd = FakeGcmd({"LANE": "lane14"})
        with pytest.raises(BambuPrinter.command_error) as exc:
            _run_by_lane(None, "AFC_BAMBU_SCAN", gcmd)
        assert str(exc.value) == (
            "AFC_BAMBU_SCAN: no Bambu unit holds a lane named 'lane14' "
            "(Bambu units: none)")


class TestFaultReason:
    RAW = ("[AMS_COMMON]en:1,mode:3,idx:0,ref:0 "
           "[AMS_COMMON]en:1,mode:3,idx:2,ref:127 "
           "[AMS_COMMON]en:1,mode:3,idx:0,ref:0 "
           "[AMS_SWITCH]timeout, assist finish stall! pos:0.1")
    AMS1_GIVE_UP = ("[AMS_DEV] STEP:odom search, odo 0.516 ... 1.185 "
                    "[AMS_DEV] STEP:odom reset tray 0 "
                    "[AMS_IDLE]set ams state switch "
                    "[AMS_COMMON]state:0,tray_now:255,tray_exit:6 "
                    "[AMS_COMMON]state:6,tray_now:255,tray_exit:6 "
                    "[AMS_LINK]en:0,mode:7,idx:255,ref:0")
    #: What the AMS 1 give-up leaves: its odometry, the state:6 verdict and
    #: the en:0,mode:7 link drop, two spaces apart.
    AMS1_REASON = ("[AMS_DEV] STEP:odom search, odo 0.516 ... 1.185  "
                   "[AMS_DEV] STEP:odom reset tray 0  "
                   "[AMS_COMMON]state:6,tray_now:255,tray_exit:6  "
                   "[AMS_LINK]en:0,mode:7,idx:255,ref:0")

    def test_the_reason_survives_and_the_chatter_does_not(self):
        assert _fault_reason(self.RAW) == (
            "[AMS_SWITCH]timeout, assist finish stall! pos:0.1")

    def test_an_unknown_dialect_is_kept(self):
        # Not a whitelist of stall wording: an unseen dialect still shows.
        assert _fault_reason("[AMS_COMMON]en:1 [AMS_WHATEVER]something new") \
            == "[AMS_WHATEVER]something new"

    def test_several_reasons_are_all_kept(self):
        assert _fault_reason("[AMS_SWITCH]stall [AMS_COMMON]en:1 "
                             "[AMS_DEV] STEP:odom tray_id error 255") == (
            "[AMS_SWITCH]stall  [AMS_DEV] STEP:odom tray_id error 255")

    def test_all_chatter_falls_back_to_the_raw_text(self):
        # Better a dump than an empty explanation.
        raw = "[AMS_COMMON]en:1,mode:3 [AMS_LINK]err_code:0x00->0x16"
        assert _fault_reason(raw) == raw
        assert _fault_reason(f"  {raw}  ") == raw

    def test_empty_stays_empty(self):
        assert _fault_reason("") == ""
        assert _fault_reason(None) is None

    def test_text_with_no_markers_is_untouched(self):
        assert _fault_reason("something went wrong") == "something went wrong"

    def test_the_ams1_give_up_survives_the_chatter_filter(self):
        assert _fault_reason(self.AMS1_GIVE_UP) == self.AMS1_REASON

    def test_the_ams1_odometry_was_never_the_problem(self):
        # [AMS_DEV] is not chatter and always survived.
        assert _fault_reason(self.AMS1_GIVE_UP).split("  ")[:2] == [
            "[AMS_DEV] STEP:odom search, odo 0.516 ... 1.185",
            "[AMS_DEV] STEP:odom reset tray 0"]

    def test_the_keep_alive_beside_the_verdict_still_goes(self):
        # state:0 and [AMS_IDLE] are chatter beside the state:6 verdict.
        reason = _fault_reason(self.AMS1_GIVE_UP)
        assert reason == self.AMS1_REASON
        assert "[AMS_COMMON]state:0" not in reason.split("  ")
        assert "[AMS_IDLE]set ams state switch" not in reason.split("  ")

    def test_the_ht_stall_state_is_kept_beside_its_words(self):
        assert _fault_reason("[AMS_COMMON]state:7,tray_now:0,tray_exit:1 "
                             "[AMS_LED]TIMEOUT error 0") == (
            "[AMS_COMMON]state:7,tray_now:0,tray_exit:1  "
            "[AMS_LED]TIMEOUT error 0")

    def test_state_zero_is_not_a_give_up(self):
        assert _fault_reason("[AMS_COMMON]state:0,tray_now:0 "
                             "[AMS_LED]TIMEOUT error 0") == (
            "[AMS_LED]TIMEOUT error 0")

    def test_en0_mode7_is_kept_off_ams_link(self):
        assert _fault_reason("[AMS_LINK]en:1,mode:3,idx:0,ref:0 "
                             "[AMS_LINK]en:0,mode:7,idx:255,ref:0") == (
            "[AMS_LINK]en:0,mode:7,idx:255,ref:0")

    def test_a_chatter_tagged_stall_is_still_a_reason(self):
        assert _fault_reason("[AMS_COMMON]en:1,mode:3 "
                             "[AMS_COMMON]pull err,bdc stall") == (
            "[AMS_COMMON]pull err,bdc stall")

    def test_ordinary_chatter_is_still_dropped(self):
        # A keep-alive with no fault signature is not rescued.
        assert _fault_reason("[AMS_COMMON]en:1,mode:3,idx:0,ref:0 "
                             "[AMS_SWITCH]feed finish, buff_pos:1.28") == (
            "[AMS_SWITCH]feed finish, buff_pos:1.28")


class TestAfcBambuAMSInit:
    class _ReadTrackingConfig(BambuConfig):
        """A unit's config section that records every option read from it."""

        def __init__(self, *args: Any, **kwargs: Any) -> None:
            """Start with nothing read."""
            super().__init__(*args, **kwargs)
            self.read: List[str] = []

        def get(self, option: str, *args: Any, **kwargs: Any) -> Any:
            """:return Any: the option, recorded in ``read``"""
            self.read.append(option)
            return super().get(option, *args, **kwargs)

        def _require(self, option: str, default: Any) -> Any:
            """:return Any: the option, recorded in ``read``"""
            self.read.append(option)
            return super()._require(option, default)

    @staticmethod
    def _tracked(values: Dict[str, Any]
                 ) -> "TestAfcBambuAMSInit._ReadTrackingConfig":
        """
        :param values: the section's options
        :return _ReadTrackingConfig: the [AFC_BambuAMS Bambu_AMS_1] section
        """
        printer = make_printer()
        opts = dict(unit_config(printer=printer)._values, **values)
        return TestAfcBambuAMSInit._ReadTrackingConfig(
            "AFC_BambuAMS Bambu_AMS_1", printer, opts)

    def test_a_unit_klipper_builds_starts_with_an_empty_latch(self):
        u = afcBambuAMS(unit_config())
        assert (u._spoolman_latched, u._scanned_bays, u._removed_bays,
                u._cleared_bays) == (set(), set(), set(), set())
        assert (u._meas_departed, u._defaults_due) == ({}, {})
        assert u._held_lanes is None and u._prep_seen is False
        assert u.logger.messages == []

    def test_the_follow_idle_ping_option_is_not_read(self):
        cfg = self._tracked({"follow_idle_ping": "1"})
        u = afcBambuAMS(cfg)
        assert "follow_idle_ping" not in cfg.read
        assert not hasattr(u, "follow_idle_ping")
        # The tracker does see the options __init__ does read.
        assert "follow_when_loaded" in cfg.read

    def test_the_unit_no_longer_carries_the_removed_attributes(self):
        # Anything still reading unit.feed_speed gets an AttributeError.
        cfg = self._tracked({"feed_speed": "50", "retract_speed": "50",
                             "max_speed": "50"})
        u = afcBambuAMS(cfg)
        for gone in ("feed_speed", "retract_speed", "max_speed"):
            assert gone not in cfg.read
            assert not hasattr(u, gone)

    def test_the_follower_options_are_not_read(self):
        cfg = self._tracked({"self_centres": "1", "follow_always": "1"})
        u = afcBambuAMS(cfg)
        assert {"self_centres", "follow_always"}.isdisjoint(cfg.read)
        assert not hasattr(u, "_send_selfcentre_flag")

    @pytest.mark.parametrize("model,heater,addr,ceiling,slots", [
        ("ams1", False, 0x0700, 65, 4), ("ams2", True, 0x0700, 65, 4),
        ("ht", True, 0x1800, 85, 1), ("boxed", False, 0x0700, 65, 4),
        ("lite", False, 0x0700, 65, 4)])
    def test_every_model_builds_through_init(self, model, heater, addr,
                                             ceiling, slots):
        # Every model-dependent line of __init__ runs; a NameError in any of
        # them fails here.
        u = afcBambuAMS(unit_config(values={"ams_model": model,
                                            "ams_index": 5}))
        assert (u.ams_model, u.has_heater, u.dry_dev_addr, u.dry_max_temp,
                u.unit_slots) == (model, heater, addr, ceiling, slots)
        # Chain index 5 sits above the four boxed ids: 0x80 + (5 - 4).
        assert (u.mc_dev_addr, u.mc_id_base, u.dry_ams_id) == (addr, 0, 0x81)
        assert u.logger.messages == []

    def test_a_named_chip_is_registered_under_that_name(self):
        u = afcBambuAMS(unit_config(
            values={"buffer_chip_name": "bambu_buffer_chain2"}))
        assert u.buffer_chip_name == "bambu_buffer_chain2"
        assert list(u.printer._bambu_buffer_chips) == ["bambu_buffer_chain2"]
        assert u.printer._bambu_buffer_chips["bambu_buffer_chain2"]._unit is u

    def test_no_name_registers_the_plain_default(self):
        u = afcBambuAMS(unit_config())
        assert u.buffer_chip_name == "bambu_buffer"
        assert list(u.printer._bambu_buffer_chips) == ["bambu_buffer"]

    def test_unknown_ams_model_raises_instead_of_defaulting_to_ams2(self):
        # A typo must not become a heated boxed unit at the wrong address.
        with pytest.raises(configparser.Error) as exc:
            afcBambuAMS(unit_config(values={"ams_model": "AMS3 "}))
        assert str(exc.value) == (
            "[AFC_BambuAMS Bambu_AMS_1] ams_model: 'ams3' is not a known "
            "model. Valid: ams1, ams2, boxed, ht, lite")


class TestAfcBambuAMSRegisterGcodeCommands:
    LANE_COMMANDS = ("AFC_BAMBU_CAPSCAN", "AFC_BAMBU_FEED",
                     "AFC_BAMBU_FOLLOWER", "AFC_BAMBU_PRIME",
                     "AFC_BAMBU_RECOVER", "AFC_BAMBU_REID", "AFC_BAMBU_SCAN")

    def test_there_is_no_manual_command_either(self):
        # Rebooting the Pico took the USB-CAN adapter down with it; there is
        # no AFC_BAMBU_RESTART, and the unit registers exactly these (the
        # three UNIT_* calibration commands come from the base unit).
        printer = make_printer()
        before = set(printer.gcode.ready_gcode_handlers)
        unit = make_bambu_unit(printer=printer)
        added = set(printer.gcode.ready_gcode_handlers) - before
        assert added == {
            "AFC_BAMBU_ARRIVAL", "AFC_BAMBU_AUTOSCAN", "AFC_BAMBU_BITE",
            "AFC_BAMBU_BUFFER_PROBE", "AFC_BAMBU_CAPSCAN",
            "AFC_BAMBU_CLEARFAULT", "AFC_BAMBU_FAULT_RELOAD",
            "AFC_BAMBU_FEED", "AFC_BAMBU_FLASH", "AFC_BAMBU_FOLLOWER",
            "AFC_BAMBU_HEATER_START", "AFC_BAMBU_HEATER_STOP",
            "AFC_BAMBU_PRIME", "AFC_BAMBU_RECOVER", "AFC_BAMBU_REID",
            "AFC_BAMBU_RELINK", "AFC_BAMBU_SAVEIDS", "AFC_BAMBU_SCAN",
            "AFC_BAMBU_SNIFF", "AFC_BAMBU_UIDS", "UNIT_BOW_CALIBRATION",
            "UNIT_CALIBRATION", "UNIT_LANE_CALIBRATION"}
        assert not hasattr(unit, "cmd_AFC_BAMBU_RESTART")

    def test_a_bare_scan_offers_unit_and_the_rest_ask_for_the_lane(self):
        # Only SCAN runs with UNIT= and no LANE=, so only its refusal offers
        # UNIT=; no angle brackets, which Moonraker reports as "Unknown".
        printer = make_printer()
        unit = make_bambu_unit(printer=printer, lanes=["lane14"])
        for cmd in self.LANE_COMMANDS:
            with pytest.raises(BambuPrinter.command_error) as exc:
                printer.gcode.run(cmd)
            if cmd == "AFC_BAMBU_SCAN":
                assert str(exc.value) == (
                    "AFC_BAMBU_SCAN: needs LANE= (one lane) or UNIT= (every "
                    "slot on that unit). Bambu units: Bambu_AMS_1")
            else:
                assert str(exc.value) == f"{cmd}: needs LANE= naming the lane"
        # The others do need the lane: UNIT= alone is refused for it.
        for cmd in self.LANE_COMMANDS:
            if cmd == "AFC_BAMBU_SCAN":
                continue
            with pytest.raises(BambuPrinter.command_error) as exc:
                printer.gcode.run(cmd, UNIT="Bambu_AMS_1")
            assert str(exc.value) == (
                f"Error on '{cmd} UNIT=Bambu_AMS_1': missing LANE")
        assert unit._bridge.sent == []
        # SCAN with UNIT= alone scans the whole unit.
        gcmd = printer.gcode.run("AFC_BAMBU_SCAN", UNIT="Bambu_AMS_1")
        assert unit._bridge.sent == [{"cmd": "scan", "unit": 0,
                                      "addr": 0x0700}]
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_SCAN: scanning 4 slot(s) on Bambu_AMS_1 at 0x0700.")]

    def test_every_unit_command_that_takes_a_lane_takes_it_alone(
            self, tmp_path):
        printer = make_printer()
        # AFC_BAMBU_FLASH looks for its firmware next to the config file.
        printer.start_args["config_file"] = str(tmp_path / "printer.cfg")
        unit = make_bambu_unit(printer=printer, lanes=["lane14"])
        defaults = {c for c, (_k, v) in printer.gcode.mux_commands.items()
                    if None in v}
        assert defaults == set(self.LANE_COMMANDS)
        # Each default routes to this unit's own handler.
        assert unit._lane_handlers == {
            c: getattr(unit, f"cmd_{c}") for c in self.LANE_COMMANDS}
        # A command added later that needs LANE= but skips the helper fails
        # here: run every unit command with UNIT= alone and see which ask.
        unit_cmds = sorted(c for c, (key, v) in
                           printer.gcode.mux_commands.items()
                           if key == "UNIT" and c.startswith("AFC_BAMBU_"))
        needs_lane = set()
        for cmd in unit_cmds:
            try:
                printer.gcode.run(cmd, UNIT="Bambu_AMS_1")
            except BambuPrinter.command_error as exc:
                if str(exc) == (
                        f"Error on '{cmd} UNIT=Bambu_AMS_1': missing LANE"):
                    needs_lane.add(cmd)
        # SCAN reads LANE= too, but runs the whole unit without it.
        assert needs_lane == set(self.LANE_COMMANDS) - {"AFC_BAMBU_SCAN"}
        assert {"cmd": "scan", "unit": 0, "addr": 0x0700} in \
            unit._bridge.sent

    def test_units_on_one_printer_share_the_lane_defaults(self):
        printer = make_printer()
        a = make_bambu_unit("Bambu_AMS_1", printer=printer,
                            lanes=["lane12", "lane13", "lane14"])
        b = make_bambu_unit("Bambu_AMS_HT_1", printer=printer, model="ht",
                            ams_index=4, lanes=["lane28"])
        g1 = printer.gcode.run("AFC_BAMBU_PRIME", LANE="lane28")
        g2 = printer.gcode.run("AFC_BAMBU_PRIME", LANE="lane14")
        assert a._bridge.sent == [{"cmd": "prime", "unit": 0, "slot": 2}]
        assert b._bridge.sent == [{"cmd": "prime", "unit": 4, "slot": 0}]
        # Each reply names the unit the lane routed to.
        assert g1.messages == [
            ("respond_info",
             "AFC_BAMBU_PRIME: sent feeder-only prime (~2s, reader dormant) "
             "to lane28 (slot 0) on Bambu_AMS_HT_1")]
        assert g2.messages == [
            ("respond_info",
             "AFC_BAMBU_PRIME: sent feeder-only prime (~2s, reader dormant) "
             "to lane14 (slot 2) on Bambu_AMS_1")]
        assert a.logger.messages == b.logger.messages == []

    def test_fault_reload_is_registered_once_per_printer_not_per_process(
            self):
        # A module-level "already registered" flag survived a RESTART and
        # left the new printer without AFC_BAMBU_FAULT_RELOAD.
        for _ in range(2):
            printer = make_printer()
            a = make_bambu_unit("Bambu_AMS_1", printer=printer)
            make_bambu_unit("Bambu_AMS_HT_1", printer=printer, model="ht",
                            ams_index=4)
            handlers = printer.gcode.ready_gcode_handlers
            assert handlers["AFC_BAMBU_FAULT_RELOAD"] == \
                a.cmd_AFC_BAMBU_FAULT_RELOAD
            assert handlers["AFC_BAMBU_UIDS"] == a.cmd_AFC_BAMBU_UIDS
            gcmd = printer.gcode.run("AFC_BAMBU_FAULT_RELOAD")
            assert gcmd.messages == [] and a.logger.messages == []


class TestAfcBambuAMSCmdAFCBambuBite:
    @staticmethod
    def _unit() -> afcBambuAMS:
        """:return afcBambuAMS: a unit configured with a 2 mm bite"""
        return make_bambu_unit(values={"tool_bite_mm": 2.0})

    def test_mm_zero_turns_the_bite_off(self):
        unit = self._unit()
        gcmd = unit.gcode.run("AFC_BAMBU_BITE", UNIT="Bambu_AMS_1", MM=0.0)
        assert unit.tool_bite_mm == 0.0
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_BITE Bambu_AMS_1: bite=OFF (single advance)  "
             "(runtime only -- a restart restores the config value)")]
        assert unit.logger.messages == []

    def test_mm_sets_the_bite(self):
        unit = self._unit()
        gcmd = unit.gcode.run("AFC_BAMBU_BITE", UNIT="Bambu_AMS_1", MM=3.5)
        assert unit.tool_bite_mm == 3.5
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_BITE Bambu_AMS_1: bite=3.50mm  (runtime only -- a "
             "restart restores the config value)")]
        assert unit.logger.messages == []

    def test_no_args_reports_without_changing(self):
        unit = self._unit()
        gcmd = unit.gcode.run("AFC_BAMBU_BITE", UNIT="Bambu_AMS_1")
        assert unit.tool_bite_mm == 2.0
        assert gcmd.messages == [
            ("respond_info", "AFC_BAMBU_BITE Bambu_AMS_1: bite=2.00mm")]
        assert unit.logger.messages == []


class TestAfcBambuAMSCmdAFCBambuFaultReload:
    def test_nothing_to_do_is_silent(self):
        unit, lane, scripts = _bambu_faulted_unit(paused=False)
        gcmd = unit.gcode.run("AFC_BAMBU_FAULT_RELOAD")
        assert (gcmd.messages, unit.logger.messages, scripts) == ([], [], [])
        assert unit._resume_needs_reload is True

    def test_a_deliberate_refusal_stops_the_resume(self):
        unit, lane, scripts = _bambu_faulted_unit(loads_ok=False)
        # Keep the command: the registered handler raises out of run().
        gcmd = FakeGcmd(command="AFC_BAMBU_FAULT_RELOAD")
        handler = unit.gcode.ready_gcode_handlers["AFC_BAMBU_FAULT_RELOAD"]
        with pytest.raises(BambuPrinter.command_error) as exc:
            handler(gcmd)
        assert str(exc.value) == (
            "Bambu_AMS_1: lane15 did NOT reload -- the toolhead is empty, so "
            "the print stays PAUSED. Clear the jam and resume again.")
        assert scripts == ["CHANGE_TOOL LANE=lane15"]
        assert gcmd.messages == [
            ("respond_info",
             "Bambu_AMS_1: reloading lane15 before resuming (a Bambu fault "
             "left the toolhead empty)...")]
        assert unit.logger.messages == []
        # Still owed, so the next resume tries the reload again.
        assert (unit._resume_needs_reload, unit._auto_recover_armed) == (
            True, True)

    def test_an_unexpected_error_does_not_cost_the_resume_button(self):
        unit, lane, scripts = _bambu_faulted_unit()
        unit.gcode.run_script_from_command = Recorder(
            raises=ValueError("bookkeeping went wrong"))
        gcmd = unit.gcode.run("AFC_BAMBU_FAULT_RELOAD")     # does not raise
        assert unit.logger.messages == [
            ("warning",
             "AFC bambu Bambu_AMS_1: reload-after-fault check failed "
             "(bookkeeping went wrong); resuming anyway. If the toolhead is "
             "empty, pause and load the lane by hand.")]
        assert gcmd.messages == [
            ("respond_info",
             "Bambu_AMS_1: reloading lane15 before resuming (a Bambu fault "
             "left the toolhead empty)...")]
        assert unit._resume_needs_reload is True


class TestAfcBambuAMSReloadBeforeResume:
    RELOADING = ("respond_info",
                 "Bambu_AMS_1: reloading lane15 before resuming (a Bambu "
                 "fault left the toolhead empty)...")

    def test_an_ordinary_resume_is_untouched(self):
        # Runs on every resume on the printer: silence is the contract.
        unit, _lane, scripts = _bambu_faulted_unit(paused=False)
        gcmd = FakeGcmd()
        unit._reload_before_resume(gcmd)
        assert (scripts, gcmd.messages) == ([], [])
        assert (unit._resume_needs_reload, unit._auto_resume_count) == (True,
                                                                         2)
        assert unit.logger.messages == []

    def test_no_pending_fault_is_untouched(self):
        unit, _lane, scripts = _bambu_faulted_unit()
        unit._resume_needs_reload = False
        gcmd = FakeGcmd()
        unit._reload_before_resume(gcmd)
        assert (scripts, gcmd.messages) == ([], [])
        # A hand-pressed resume still hands back the recovery budget.
        assert unit._auto_resume_count == 0
        assert unit.logger.messages == []

    def test_a_resume_the_recovery_runs_itself_keeps_the_count(self):
        unit, _lane, scripts = _bambu_faulted_unit()
        unit._in_auto_recover = True
        gcmd = FakeGcmd()
        unit._reload_before_resume(gcmd)
        assert unit._auto_resume_count == 2
        # The reload itself still runs.
        assert scripts == ["CHANGE_TOOL LANE=lane15"]
        assert gcmd.messages == [self.RELOADING]
        assert (unit._resume_needs_reload, unit._auto_recover_armed) == (
            False, False)
        assert unit.logger.messages == []

    def test_an_already_loaded_lane_is_not_reloaded(self):
        unit, _lane, scripts = _bambu_faulted_unit(tool_loaded=True)
        gcmd = FakeGcmd()
        unit._reload_before_resume(gcmd)
        assert (scripts, gcmd.messages) == ([], [])
        assert unit._resume_needs_reload is False
        assert unit._auto_recover_armed is True
        assert unit.logger.messages == []

    def test_a_faulted_lane_is_reloaded_before_the_resume(self):
        unit, lane, scripts = _bambu_faulted_unit()
        gcmd = FakeGcmd()
        unit._reload_before_resume(gcmd)
        assert scripts == ["CHANGE_TOOL LANE=lane15"]
        assert lane.tool_loaded is True
        assert (unit._resume_needs_reload, unit._auto_recover_armed) == (
            False, False)
        assert gcmd.messages == [self.RELOADING]
        assert unit.logger.messages == []

    def test_a_reload_that_does_not_take_refuses_to_resume(self):
        unit, _lane, scripts = _bambu_faulted_unit(loads_ok=False)
        gcmd = FakeGcmd()
        with pytest.raises(BambuPrinter.command_error) as exc:
            unit._reload_before_resume(gcmd)
        assert str(exc.value) == (
            "Bambu_AMS_1: lane15 did NOT reload -- the toolhead is empty, so "
            "the print stays PAUSED. Clear the jam and resume again.")
        assert scripts == ["CHANGE_TOOL LANE=lane15"]
        assert gcmd.messages == [self.RELOADING]
        # Still owed, so a second press tries again rather than giving up.
        assert (unit._resume_needs_reload, unit._auto_recover_armed) == (
            True, True)
        assert unit.logger.messages == []


class TestAfcBambuAMSCmdAFCBambuClearfault:
    @staticmethod
    def _run(before: int, after: int, ams_index: int = 0
             ) -> Tuple[afcBambuAMS, FakeGcmd]:
        """
        Run AFC_BAMBU_CLEARFAULT on a unit reporting ``before``, which
        reports ``after`` once the clear is sent.

        :param before: the unit's state before the burst
        :param after: its state after
        :param ams_index: the unit's chain index
        :return tuple: (unit, the command)
        """
        def answer(bridge: FakeBridge, frame: dict) -> None:
            """The unit's state once the clear went out."""
            bridge.status = {"units": [{"n": ams_index, "ustate": after}]}

        bridge = FakeBridge(status={"units": [{"n": ams_index,
                                               "ustate": before}]},
                            on_send=answer)
        unit = make_bambu_unit(ams_index=ams_index, bridge=bridge)
        t0 = unit.reactor.monotonic()
        gcmd = unit.gcode.run("AFC_BAMBU_CLEARFAULT", UNIT="Bambu_AMS_1")
        assert unit.reactor.monotonic() == pytest.approx(t0 + 2.6)
        # The verdict goes to the console only.
        assert unit.logger.messages == []
        return unit, gcmd

    def test_the_clear_names_the_unit(self):
        # Unaddressed, the clear lands on whichever unit was last driven.
        unit, gcmd = self._run(0x07, 0x00, ams_index=3)
        assert unit._bridge.sent == [{"cmd": "clearfault", "unit": 3}]
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_CLEARFAULT: Bambu_AMS_1: cleared (state 7 -> 0); the "
             "unit accepted the operation and left its park.")]

    def test_a_real_clear_is_reported_as_one(self):
        unit, gcmd = self._run(0x07, 0x00)
        assert unit._bridge.sent == [{"cmd": "clearfault", "unit": 0}]
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_CLEARFAULT: Bambu_AMS_1: cleared (state 7 -> 0); the "
             "unit accepted the operation and left its park.")]

    def test_a_unit_that_was_never_faulted_is_not_called_cleared(self):
        # Nothing happened; say so, and point at what might help.
        _unit, gcmd = self._run(0x00, 0x00)
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_CLEARFAULT: Bambu_AMS_1: nothing to clear -- the unit "
             "was not in a fault state before the burst (state 0) and is not "
             "now (0). The clear was still sent to unit 0. If its LEDs are "
             "red, the cause is not a parked feeder: try AFC_BAMBU_RELINK "
             "UNIT=Bambu_AMS_1, which re-registers the unit without a power "
             "cycle.")]

    def test_state_6_counts_as_faulted_both_ways(self):
        # Going in: 6 -> 0 is a real clear, not "nothing to clear".
        _unit, gcmd = self._run(0x06, 0x00)
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_CLEARFAULT: Bambu_AMS_1: cleared (state 6 -> 0); the "
             "unit accepted the operation and left its park.")]
        # Staying: 7 -> 6 is still faulted.
        _unit, gcmd = self._run(0x07, 0x06)
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_CLEARFAULT: Bambu_AMS_1: STILL FAULTED (state 6). The "
             "unit will not accept a fresh operation while the jam is there "
             "-- relieve the pressure (the buffer coming off the floor is the "
             "sign) and run this again.")]

    def test_a_still_faulted_unit_is_not_reported_as_cleared(self):
        _unit, gcmd = self._run(0x07, 0x07)
        assert gcmd.messages == [
            ("respond_info",
             "AFC_BAMBU_CLEARFAULT: Bambu_AMS_1: STILL FAULTED (state 7). The "
             "unit will not accept a fresh operation while the jam is there "
             "-- relieve the pressure (the buffer coming off the floor is the "
             "sign) and run this again.")]

    def test_no_bridge_is_refused(self):
        unit = make_bambu_unit(offline=True)
        gcmd = FakeGcmd({"UNIT": "Bambu_AMS_1"},
                        command="AFC_BAMBU_CLEARFAULT")
        with pytest.raises(BambuPrinter.command_error) as exc:
            unit.gcode.ready_gcode_handlers["AFC_BAMBU_CLEARFAULT"](gcmd)
        assert str(exc.value) == "AFC_BAMBU_CLEARFAULT: bridge not connected"
        assert (gcmd.messages, unit.logger.messages) == ([], [])


class TestAfcBambuAMSMcaddrAckStr:
    class _OldBridge(FakeBridge):
        """A bridge from before the mcaddr acknowledgement existed."""

        mcaddr_ack = None

    class _DownBridge(FakeBridge):
        """A bridge whose acknowledgement table cannot be read."""

        def mcaddr_ack(self, unit: int) -> Optional[int]:
            """:raises RuntimeError: always"""
            raise RuntimeError("down")

    @staticmethod
    def _unit(bridge: Optional[FakeBridge], ams_index: int = 0
              ) -> afcBambuAMS:
        """
        :param bridge: the unit's bridge, or None for none
        :param ams_index: its chain index
        :return afcBambuAMS: the unit
        """
        return make_bambu_unit(ams_index=ams_index, bridge=bridge,
                               offline=bridge is None)

    def test_no_bridge_is_unknown(self):
        assert self._unit(None)._mcaddr_ack_str() == "?"

    def test_old_bridge_without_the_accessor_is_unknown(self):
        assert self._unit(self._OldBridge())._mcaddr_ack_str() == "?"

    def test_never_acknowledged_is_none_not_zero(self):
        assert self._unit(FakeBridge())._mcaddr_ack_str() == "none"

    def test_acknowledged_as_unset_is_zero_not_none(self):
        bridge = FakeBridge()
        bridge.mcaddr_acks[0] = 0
        assert self._unit(bridge)._mcaddr_ack_str() == "0x0000"

    def test_an_applied_address_is_shown_in_hex(self):
        bridge = FakeBridge()
        bridge.mcaddr_acks[0] = 0x1800
        assert self._unit(bridge)._mcaddr_ack_str() == "0x1800"

    def test_it_asks_about_its_own_chain_index(self):
        bridge = FakeBridge()
        bridge.mcaddr_acks.update({0: 0x1800, 2: 0x0700})
        assert self._unit(bridge, ams_index=2)._mcaddr_ack_str() == "0x0700"

    def test_a_throwing_bridge_is_unknown_not_a_crash(self):
        assert self._unit(self._DownBridge())._mcaddr_ack_str() == "?"


class TestAfcBambuAMSCmdAFCBambuScan:
    class _DownMoonraker:
        """Moonraker refusing every lane-data post (it is restarting)."""

        def __init__(self) -> None:
            """Start with no posts."""
            self.posts: List[Dict[str, Any]] = []

        def send_lane_data(self, data: Dict[str, Any]) -> None:
            """
            :param data: the lane record, recorded
            :raises ConnectionError: always
            """
            self.posts.append(data)
            raise ConnectionError("Moonraker is restarting")

        def remove_database_entry(self, namespace: str, key: str) -> None:
            """:raises ConnectionError: always"""
            raise ConnectionError("Moonraker is restarting")

    TRAY15 = "4e3177c31fea42d08bc240c818a37f80"

    @staticmethod
    def _verdict(slot: int, verdict: str = "none", seq: Any = None,
                 res: Any = None, mat: str = "-", uid: str = "-",
                 present: bool = False) -> LogLine:
        """
        A bay's scan verdict line, as the status pass logs it.

        :param slot: the bay
        :param verdict: the verdict word
        :param seq: the firmware's scan sequence
        :param res: the firmware's scan result
        :param mat: the record's material
        :param uid: the record's tag
        :param present: the record's presence
        :return LogLine: the debug line
        """
        return ("debug",
                f"AFC bambu Bambu_AMS_1: slot {slot} scan verdict -> "
                f"{verdict} (fw seq={seq} res={res} | record: mat={mat} "
                f"uid={uid} present={present})")

    def _lane15(self, monkeypatch: pytest.MonkeyPatch
                ) -> Tuple[afcBambuAMS, _HeldSpoolmanClient]:
        """
        Printer 1's lane15 as AFC restored it at a restart, with no Spoolman
        spool: PREP run and its bay claimed, the prime fired, and the bay's
        record carrying the tag 95F2C30C. Spoolman does not know the tag yet.

        :return tuple: (unit, the Spoolman client)
        """
        printer = make_printer()
        slots = [slot_info(i, present=False) for i in range(3)]
        slots.append(slot_info(3, material="PLA Basic", color="0086D6",
                               uid="95f2c30c", tray_uid=self.TRAY15,
                               sku="GFA00", weight=1000, sseq=0, sres=0,
                               mseq=0, mpct=0))
        lane15 = LaneSpec("lane15", 3, prep=True, material="PLA",
                          color="#0086D6", weight=1000,
                          extras={"sub_type": "Basic"},
                          values={"map": "T15"})
        printer.afc.moonraker = self._DownMoonraker()
        unit = make_bambu_unit(printer=printer,
                               lanes=["lane12", "lane13", "lane14", lane15],
                               slots=slots, prep_seen=True, scan_primed=True,
                               values={"auto_scan": False})
        unit._afc_owned = {3}                 # PREP: the lane came back
        client = _HeldSpoolmanClient()
        use_spoolman_client(monkeypatch, client)
        make_bambu_spoolman(unit, spoolman_url="http://spoolman:7912")
        return unit, client

    @staticmethod
    def _frames(unit: afcBambuAMS, n: int) -> None:
        """
        :param unit: the unit
        :param n: status passes, the lookups they post answered
        """
        for _ in range(n):
            unit._sync_lanes()
        unit.reactor.run_callbacks()

    def test_a_scan_that_reads_no_new_measurement_still_asks_again(
            self, monkeypatch):
        # AFC_BAMBU_SCAN after a restart lookup that missed, where the unit
        # re-reads the tag and its cycle ends without a measurement: the scan
        # forgot the miss, so the tag is asked about again and linked.
        unit, client = self._lane15(monkeypatch)
        lane = unit.lanes["lane15"]
        tagged = {"mat": "PLA Basic", "uid": "95f2c30c", "present": True}
        self._frames(unit, 3)
        assert client.asked == [("search_spools",)]
        assert unit._spoolman_latched == {3}
        assert unit.afc.spool.calls == []
        # Nothing AFC restored moved; the variant fill (vendor and name) is
        # the only write. Moonraker refused its post; it was saved all the
        # same.
        assert (lane.spool_id, lane.material, lane.sub_type, lane.color,
                lane.weight) == (None, "PLA", "Basic", "#0086D6", 1000)
        assert (lane.spool_vendor, lane.filament_name) == (
            "Bambu", "Bambu PLA Basic")
        posts = unit.afc.moonraker.posts
        assert [(p["key"], p["value"]["vendor_name"]) for p in posts] == [
            ("T15", "Bambu")]
        assert unit.afc.save_vars.calls == [((), {})]
        assert unit.logger.messages == [
            self._verdict(0), self._verdict(1), self._verdict(2),
            self._verdict(3, seq=0, res=0, **tagged),
            ("info", "AFC bambu Bambu_AMS_1: lane15 -- filling in vendor and "
                     "name from the bay's record (PLA Basic)"),
            ("debug", "AFC bambu Bambu_AMS_1: lane15 has no Spoolman spool "
                      "and its bay's tag 95F2C30C (PLA Basic) matches the "
                      "lane -- looking the tag up in Spoolman; the lane is "
                      "left as AFC restored it")]
        unit.logger.messages.clear()

        # Latched: more frames ask nothing.
        self._frames(unit, 3)
        assert client.asked == [("search_spools",)]
        assert unit.logger.messages == []

        # The spool is added to Spoolman; the operator scans the lane.
        client.spools.append(_held_spool(136, chips="95F2C30C",
                                         tray=self.TRAY15))
        gcmd = unit.gcode.run("AFC_BAMBU_SCAN", LANE="lane15")
        assert gcmd.messages == [(
            "respond_info",
            "AFC_BAMBU_SCAN: scanning lane15 (slot 3) on Bambu_AMS_1 at "
            "0x0700; material lands when the tag reads, remaining % when the "
            "measurement finishes (~30s).")]
        assert unit._bridge.sent == [{"cmd": "capscan", "trig": 1, "ins": 0,
                                      "unit": 0, "slot": 3}]
        assert unit._spoolman_latched == set()

        # While the unit works the bay is held, and nothing is asked.
        self._frames(unit, 2)
        assert client.asked == [("search_spools",)]
        assert unit.logger.messages == [
            self._verdict(3, "waiting", seq=0, res=0, **tagged)]
        unit.logger.messages.clear()

        # The unit re-reads the tag and ends its cycle with no measurement.
        unit._slots[3] = dict(unit._slots[3], scan_seq=2, scan_res=1)
        self._frames(unit, 3)
        assert client.asked == [("search_spools",), ("search_spools",)]
        assert unit.afc.spool.calls == [("set_spoolID", (lane, 136), {})]
        assert client.calls == [("write_spool_metadata",
                                 (136, {"uid": "95f2c30c"}))]
        assert unit.logger.messages == [
            self._verdict(3, "read", seq=2, res=1, **tagged),
            ("debug", "AFC bambu Bambu_AMS_1: lane15 tag -- PLA Basic GFA00 "
                      "| color #0086D6 | uid 95F2C30C | remaining no "
                      "measurement yet | nominal 1000 g | nozzle ?-?C | bed "
                      "55C (material)"),
            self._verdict(3, seq=2, res=1, **tagged),
            ("debug", f"AFC bambu Bambu_AMS_1: matched lane15 to Spoolman "
                      f"spool 136 by tray UID {self.TRAY15}")]
        assert unit.gcode.messages == []

    def test_a_backstop_that_cannot_be_armed_still_opens_the_scan(
            self, monkeypatch):
        # The backstop timer is best effort: the scan opens without it.
        unit = make_bambu_unit(lanes=["lane12"], values={"auto_scan": False})
        arm = Recorder(raises=RuntimeError("reactor closing"))
        monkeypatch.setattr(unit.afc.reactor, "register_callback", arm)
        now = unit.afc.reactor.monotonic()
        gcmd = unit.gcode.run("AFC_BAMBU_SCAN", LANE="lane12")
        assert arm.call_count == 1
        assert unit._scan_t0[0] == now
        assert unit._bridge.sent == [{"cmd": "capscan", "trig": 1, "ins": 0,
                                      "unit": 0, "slot": 0}]
        assert gcmd.messages == [(
            "respond_info",
            "AFC_BAMBU_SCAN: scanning lane12 (slot 0) on Bambu_AMS_1 at "
            "0x0700; material lands when the tag reads, remaining % when the "
            "measurement finishes (~30s).")]
        assert unit.logger.messages == []


class TestAfcBambuAMSCapOpenPending:
    def test_a_bad_clock_does_not_break_the_marker(self, monkeypatch):
        unit = make_bambu_unit(model="ht")

        def _broken() -> float:
            """:raises RuntimeError: always"""
            raise RuntimeError("clock")

        monkeypatch.setattr(unit.afc.reactor, "monotonic", _broken)
        unit._cap_open_pending(0)
        assert unit._cap_pending == {0: 0.0}
        assert unit._cap_pending_slot == 0      # still marked
        assert unit._cap_pending_t0 == 0.0
        assert unit._cap_pending_asked == set()

    def test_an_asked_window_opens_at_the_clock_and_voids_an_old_answer(self):
        unit = make_bambu_unit(model="ht")
        unit._cap_answered = {0, 2}
        unit._cap_open_pending(0, asked=True)
        assert unit._cap_pending == {0: 100.0}
        assert unit._cap_pending_slot == 0
        assert unit._cap_pending_t0 == 100.0
        assert unit._cap_pending_asked == {0}
        assert unit._cap_answered == {2}
        # An insert edge on the same bay is not a command's question.
        unit.reactor.now = 110.0
        unit._cap_open_pending(0)
        assert unit._cap_pending == {0: 110.0}
        assert unit._cap_pending_asked == set()
        assert unit.logger.messages == []


class TestAfcBambuAMSCapLivePending:
    def test_an_empty_map_is_an_answer(self):
        # The state pruning used to leave behind: the map emptied, the legacy
        # marker still naming the bay. Read as "nothing recorded", it came
        # back as {2: t0} on every call -- the wait that never ended.
        unit = make_bambu_unit(printer=make_printer(now=12000.0))
        unit._cap_pending = {}
        unit._cap_pending_slot, unit._cap_pending_t0 = 2, 9798.08
        assert unit._cap_live_pending() == {}
        assert unit._cap_pending_slot is None
        # With no map at all the marker is still honoured, for a unit that
        # never opened a window through the map.
        other = make_bambu_unit(printer=make_printer(now=12000.0))
        assert not hasattr(other, "_cap_pending")
        other._cap_pending_slot, other._cap_pending_t0 = 3, 11990.0
        assert other._cap_live_pending() == {3: 11990.0}
        assert other._cap_pending_slot == 3
        assert unit.logger.messages == []
        assert other.logger.messages == []


class TestAfcBambuAMSMeasureInFlightSlot:
    class _HiccupBridge(FakeBridge):
        """A bridge whose terminal lookup fails."""

        def last_terminal(self, addr: Optional[int]) -> Optional[float]:
            """:raises RuntimeError: always"""
            raise RuntimeError("bridge hiccup")

    @staticmethod
    def _bridge(terminal: Optional[float] = None,
                owner: Optional[str] = None) -> FakeBridge:
        """
        :param terminal: when 0x0700 last narrated the end of a measure
        :param owner: who holds the bus claim
        :return FakeBridge: the bridge
        """
        bridge = FakeBridge()
        if terminal is not None:
            bridge.terminal[0x0700] = terminal
        bridge.claimed_bus = owner
        return bridge

    @staticmethod
    def _busy(pend: Optional[int], t0: float, now: float,
              bridge: Optional[FakeBridge] = None,
              offline: bool = False) -> afcBambuAMS:
        """
        The unit Bambu_AMS_2 (0x0700), its measure on ``pend`` opened at
        ``t0`` and the clock at ``now``.

        :param pend: the bay measuring, or None for none
        :param t0: when it started
        :param now: the time asked at
        :param bridge: its bridge; a quiet one when None
        :param offline: no bridge at all
        :return afcBambuAMS: the unit
        """
        unit = make_bambu_unit("Bambu_AMS_2", printer=make_printer(now=t0),
                               bridge=bridge, offline=offline)
        if pend is not None:
            unit._cap_open_pending(pend, asked=True)
        unit.reactor.now = now
        return unit

    def test_no_pending_measure_is_idle(self):
        assert self._busy(None, 0.0, 100.0)._measure_in_flight_slot() is None

    def test_a_recent_measure_reads_busy_on_its_slot(self):
        # A second manual measure inside the window is refused so it is not
        # silently dropped by the one-bay-at-a-time firmware.
        assert self._busy(2, 100.0, 130.0)._measure_in_flight_slot() == 2

    def test_a_stale_measure_marker_is_not_busy(self):
        # Past the window a lingering marker (a one-edged measure) is treated
        # as done, never a permanent block.
        assert self._busy(2, 100.0, 200.0)._measure_in_flight_slot() is None
        # The window is 50 s: at its edge the measure still counts.
        assert self._busy(2, 100.0, 150.0)._measure_in_flight_slot() == 2

    def test_a_narrated_ending_releases_the_guard(self):
        bridge = self._bridge(terminal=120.0, owner="Bambu_AMS_2")
        unit = self._busy(0, 100.0, 130.0, bridge)
        assert unit._measure_in_flight_slot() is None
        # The marker stays: it still gates a measurement landing late.
        assert unit._cap_pending_slot == 0

    def test_an_ending_from_before_this_measure_is_not_ours(self):
        # The previous cycle's terminal. Older than t0, so it says nothing
        # about the measure now running.
        bridge = self._bridge(terminal=90.0, owner="Bambu_AMS_2")
        assert self._busy(0, 100.0, 130.0, bridge)._measure_in_flight_slot() == 0

    def test_a_unit_that_has_narrated_no_ending_is_still_busy(self):
        bridge = self._bridge(terminal=None, owner="Bambu_AMS_2")
        assert self._busy(0, 100.0, 130.0, bridge)._measure_in_flight_slot() == 0

    def test_another_units_ending_does_not_release_us(self):
        # THE BOXED UNITS SHARE 0x0700 and last_terminal is keyed by address,
        # so AMS 1's ending would otherwise answer for AMS 2. The bus claim
        # is the discriminator.
        bridge = self._bridge(terminal=120.0, owner="Bambu_AMS_1")
        assert self._busy(0, 100.0, 130.0, bridge)._measure_in_flight_slot() == 0

    def test_an_unclaimed_bus_still_trusts_the_ending(self):
        # The claim is released after adoption, so a free bus with the marker
        # still set is exactly the case being fixed.
        bridge = self._bridge(terminal=120.0, owner=None)
        assert self._busy(0, 100.0, 130.0, bridge)._measure_in_flight_slot() is None

    def test_a_bridge_hiccup_leaves_the_guard_standing(self):
        unit = self._busy(0, 100.0, 130.0, self._HiccupBridge())
        assert unit._measure_in_flight_slot() == 0

    def test_no_bridge_falls_back_to_the_window(self):
        unit = self._busy(0, 100.0, 130.0, offline=True)
        assert unit._bridge is None
        assert unit._measure_in_flight_slot() == 0

    def test_a_clock_that_cannot_be_read_is_idle(self, monkeypatch):
        unit = self._busy(0, 100.0, 130.0)

        def _broken() -> float:
            """:raises RuntimeError: always"""
            raise RuntimeError("clock")

        monkeypatch.setattr(unit.afc.reactor, "monotonic", _broken)
        assert unit._measure_in_flight_slot() is None


class TestAfcBambuAMSStartCapscan:
    @staticmethod
    def _verdict(slot: int, mat: str, uid: str, present: bool) -> LogLine:
        """
        A bay's scan verdict line with no scan in flight.

        :param slot: the bay
        :param mat: the record's material
        :param uid: the record's tag
        :param present: the record's presence
        :return LogLine: the debug line
        """
        return ("debug",
                f"AFC bambu Bambu_AMS_1: slot {slot} scan verdict -> none (fw "
                f"seq=None res=None | record: mat={mat} uid={uid} "
                f"present={present})")

    def test_a_new_window_forgets_an_old_answer(self):
        # A stamp adopted during one window says nothing about the next one
        # on the same bay.
        slots = [slot_info(0, present=False),
                 slot_info(1, material="PLA Basic", uid="d13fdb0e",
                           weight=1000),
                 slot_info(2, weight=1000), slot_info(3, present=False)]
        # The lanes feed a hub with its own switch.
        unit = make_bambu_unit(printer=make_printer(now=9707.572),
                               model="ams1", ams_index=1,
                               lanes=["lane7", "lane8", "lane9", "lane10"],
                               slots=slots, prep_seen=True, scan_primed=True,
                               virtual_hub=False)
        assert unit._start_capscan(1, cali=True)
        assert unit._bridge.sent == [{"cmd": "cali", "auto": 0, "unit": 1,
                                      "slot": 1}]
        assert unit._bridge.claimed_bus == "Bambu_AMS_1"
        assert unit._cap_pending == {1: 9707.572}
        assert unit._cap_pending_asked == {1}
        assert unit.logger.messages == []
        unit._slots[1] = dict(unit._slots[1], meas_seq=3, meas_pct=56)
        unit._sync_lanes()
        assert unit._cap_answered == {1}
        assert unit.lanes["lane8"].weight == 460
        assert unit.logger.messages == [
            self._verdict(0, "-", "-", False),
            self._verdict(1, "PLA Basic", "d13fdb0e", True),
            ("debug", "capsample unit=Bambu_AMS_1 slot=1 lane=lane8 "
                      "spool=None material='PLA Basic' density=1.24 "
                      "pct_raw=56 radius_m=None circ_m=None save_r_m=None "
                      "radius_src=none source='physical AMS measurement' "
                      "nominal=1000 grams_written=460 grams_modelled=460"),
            ("info", "Bambu_AMS_1 lane8: tag read: PLA Basic [tag D13FDB0E]. "
                     "Measured about 56% left -- roughly 460 g of a 1000 g "
                     "spool; kept on the lane -- the Spoolman module "
                     "([AFC_BambuAMS_rfid]) is off."),
            ("info", "AFC bambu Bambu_AMS_1: applied tag to lane8: "
                     "Bambu PLA Basic"),
            ("debug", "AFC bambu Bambu_AMS_1: lane8 tag -- PLA Basic | color "
                      "? | uid D13FDB0E | remaining 56% MEASURED (~460 g) | "
                      "nominal 1000 g | nozzle ?-?C | bed 55C (material)"),
            self._verdict(2, "-", "-", True),
            self._verdict(3, "-", "-", False)]
        unit.logger.messages.clear()

        unit.reactor.now = 9760.0
        assert unit._start_capscan(1, cali=True)
        assert unit._cap_answered == set()
        assert unit._cap_pending == {1: 9760.0}
        assert unit._bridge.sent == [
            {"cmd": "cali", "auto": 0, "unit": 1, "slot": 1},
            {"cmd": "cali", "auto": 0, "unit": 1, "slot": 1}]
        assert unit.logger.messages == []

        # Unanswered past 180 s, the window ends and says so, once.
        unit.reactor.now = 9940.1
        unit._status_apply_measurements({"slots": []})
        unit._status_apply_measurements({"slots": []})
        assert unit._cap_pending == {}
        assert unit._cap_pending_slot is None
        assert unit.logger.messages == [(
            "info", "AFC bambu Bambu_AMS_1: lane8 (slot 1) capscan ended "
                    "without a measurement (no reading within 180 s); it is "
                    "no longer waiting for one")]


class TestAfcBambuAMSCmdAFCBambuCapscan:
    ARMED = ("AFC_BAMBU_CAPSCAN: capacity re-scan armed for lane8 (slot 1) on "
             "Bambu_AMS_1 -- the AMS pulls the spool, re-reads the tag and "
             "measures remain%; check the slot's remain_pct in about a minute")
    WARNED = ("AFC bambu Bambu_AMS_1: lane8 is bound to Spoolman spool 164, "
              "and with the Spoolman module ([AFC_BambuAMS_rfid]) off this "
              "measurement stays on the lane and is not written to that "
              "spool. AFC reloads a bound lane's weight from Spoolman at "
              "restart, so lane8 and spool 164 can disagree.")

    @staticmethod
    def _capscan(section: Optional[bool], spool_id: Optional[int],
                 afc_spoolman: Optional[str]) -> List[LogLine]:
        """
        AFC_BAMBU_CAPSCAN LANE=lane8 on a real unit, the measurement sent.

        :param section: [AFC_BambuAMS_rfid] enabled, disabled, or absent (None)
        :param spool_id: lane8's Spoolman spool
        :param afc_spoolman: AFC core's spoolman setting
        :return list: what the unit logged
        """
        printer = make_printer()
        if section is not None:
            make_spoolman_section(printer, enabled=section)
        slots = [slot_info(0, present=False),
                 slot_info(1, material="PLA Basic", uid="d13fdb0e",
                           weight=1000)]
        unit = make_bambu_unit(
            printer=printer,
            lanes=["lane7", LaneSpec("lane8", 1, spool_id=spool_id)],
            slots=slots, prep_seen=True, scan_primed=True)
        unit.afc.spoolman = afc_spoolman
        gcmd = printer.gcode.run("AFC_BAMBU_CAPSCAN", LANE="lane8")
        assert gcmd.messages == [
            ("respond_info", TestAfcBambuAMSCmdAFCBambuCapscan.ARMED)]
        assert unit._bridge.sent == [{"cmd": "cali", "auto": 0, "unit": 0,
                                      "slot": 1}]
        assert printer.gcode.messages == []
        return unit.logger.messages

    def test_a_bound_lane_with_the_module_off_is_warned_at_capscan(self):
        # It says they can disagree, and leaves it there: which figure a lane
        # shows after a restart is the restart's business, not this warning's.
        assert self._capscan(None, 164, "http://spoolman:7912") == [
            ("warning", self.WARNED)]

    @pytest.mark.parametrize("section, spool_id, afc_spoolman", [
        (True, 164, "http://spoolman:7912"),     # the module writes the spool
        (None, None, "http://spoolman:7912"),    # nothing bound, nothing reloads
        (None, 164, None),                       # AFC has no Spoolman to reload from
    ], ids=["module-on", "unbound", "afc-without-spoolman"])
    def test_no_capscan_warning_otherwise(self, section, spool_id,
                                          afc_spoolman):
        assert self._capscan(section, spool_id, afc_spoolman) == []

    def test_enabled_false_counts_as_the_module_off(self):
        assert self._capscan(False, 164, "http://spoolman:7912") == [
            ("warning", self.WARNED)]


class TestAfcBambuAMSCmdAFCBambuHeaterStart:
    """
    ONE AMS 2 Pro may dry off the bus wire: a second collapses the supply
    about 3s after its heater engages and resets every unit on the wire. The
    unit reports its own 24V jack in the telemetry it streams while drying:
    ~23.8 with the adapter in, ~0.5 without.
    """

    PREFIX = "AFC_BAMBU_HEATER_START: "
    # The plain 55C/480min frame an AMS HT at chain index 4 is sent.
    HT_FRAME = {"cmd": "dry", "unit": 4, "on": 1, "temp": 55, "time": 480,
                "rotate": 0, "addr": 0x1800, "amsid": 128}

    @staticmethod
    def _bus_refusal(name: str, volts: str) -> str:
        """
        :param name: the sibling drying off the bus
        :param volts: its jack reading, as printed
        :return str: the refusal, without the command prefix
        """
        return (f"{name} is already drying off the BUS ({volts}V at its 24V "
                f"jack, so nothing is plugged into it). Two units heating off "
                f"the bus wire collapse the supply and reset every AMS on it. "
                f"Either stop {name}, or plug a 24V adapter into it -- once "
                f"it reports ~24V this start goes through with it still "
                f"running. FORCE=1 overrides.")

    @staticmethod
    def _silent_refusal(name: str) -> str:
        """
        :param name: the sibling drying with no power report yet
        :return str: the refusal, without the command prefix
        """
        return (f"{name} is drying and has not reported its power source "
                f"yet, so there is no way to tell whether it is running off "
                f"the bus. Wait ~10s for it to report and start again, or add "
                f"FORCE=1 if you know it is on its own 24V adapter.")

    @staticmethod
    def _rotate_off(name: str, lanes: str) -> LogLine:
        """
        :param name: the unit starting
        :param lanes: the committed lanes, as listed
        :return LogLine: the console line dropping the rotation
        """
        return ("respond_info",
                f"AFC_BAMBU_HEATER_START: ROTATE disabled for {name} -- "
                f"{lanes} still has filament in the feeder, and the unit will "
                f"not turn a spool that does. Unload the bays and leave the "
                f"spools free to spin to dry with rotation. Drying without "
                f"it.")

    @staticmethod
    def _bus(volts: Dict[int, Optional[float]], starter: int, *,
             now: float = 1000.0, seen: float = 1000.0, drying: bool = True,
             starter_values: Optional[Dict[str, Any]] = None
             ) -> Tuple[afcBambuAMS, Dict[int, afcBambuAMS], BambuPrinter]:
        """
        AMS 2 Pros on one bridge: Bambu_AMS_<i+1> at chain index i for each
        entry of ``volts`` (already heating, reporting that many volts at its
        jack, or nothing yet for None), and the one about to start at
        ``starter``.

        :param volts: chain index -> jack reading of a sibling
        :param starter: the starting unit's chain index
        :param now: the clock
        :param seen: when the siblings' readings were narrated
        :param drying: whether the siblings' cycles were started here
        :param starter_values: further options for the starting unit
        :return tuple: (starting unit, siblings by index, printer)
        """
        printer = make_printer(now=now)
        bridge = FakeBridge()
        siblings = {}
        for i, v in volts.items():
            siblings[i] = make_bambu_unit(f"Bambu_AMS_{i + 1}",
                                          printer=printer, ams_index=i,
                                          bridge=bridge, drying=drying)
            if v is not None:
                bridge._chmb_by_unit[i] = {"ad_v": v, "seen": seen,
                                           "temp": 40.0, "state": 2}
        unit = make_bambu_unit(f"Bambu_AMS_{starter + 1}", printer=printer,
                               ams_index=starter, bridge=bridge,
                               values=starter_values)
        return unit, siblings, printer

    @staticmethod
    def _start(unit: afcBambuAMS, **params: Any) -> FakeGcmd:
        """
        AFC_BAMBU_HEATER_START UNIT=<unit> TEMP=55 TIME=480 plus ``params``.

        :param unit: the unit to start
        :return FakeGcmd: the command, with its responses
        """
        args: Dict[str, Any] = {"TEMP": 55, "TIME": 480}
        args.update(params)
        return unit.gcode.run("AFC_BAMBU_HEATER_START", UNIT=unit.name,
                              **args)

    def _refused(self, unit: afcBambuAMS, gcmd: FakeGcmd, reason: str
                 ) -> None:
        """
        :param unit: the unit that was to start
        :param gcmd: its command
        :param reason: the refusal, without the command prefix
        """
        assert gcmd.messages == [("respond_info", self.PREFIX + reason)]
        assert unit._bridge.sent == []         # NOTHING reached the bus
        assert unit._drying is False
        # The panel's card carries the reason too, not just the console.
        assert unit._dry_host_refusal == reason
        assert unit.logger.messages == []

    @staticmethod
    def _started(unit: afcBambuAMS, gcmd: FakeGcmd) -> None:
        """
        :param unit: Bambu_AMS_2 (index 1) or Bambu_AMS_4 (index 3)
        :param gcmd: its command, which started a plain 55C/480min dry
        """
        idx = unit.ams_index
        assert gcmd.messages == [(
            "respond_info",
            f"AFC_BAMBU_HEATER_START: {unit.name} drying at 55C for 480min "
            f"(addr 0x0700, id {idx}).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": idx, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x0700, "amsid": idx}]
        assert unit._drying is True
        assert unit._dry_host_refusal == ""
        assert unit.logger.messages == []

    @staticmethod
    def _unit(model: str = "ams2", ams_index: int = 1,
              name: str = "Bambu_AMS_2",
              lanes: Sequence[LaneSpec] = ()) -> afcBambuAMS:
        """
        :param model: ams_model
        :param ams_index: chain index
        :param name: the unit's name
        :param lanes: its lanes
        :return afcBambuAMS: a unit alone on its bridge
        """
        return make_bambu_unit(name, printer=make_printer(now=1000.0),
                               model=model, ams_index=ams_index,
                               lanes=list(lanes))

    # ── the bus-supply interlock ──────────────────────────────────────────

    def test_second_bus_powered_dryer_is_refused(self):
        unit, _sib, _p = self._bus({0: 0.5}, starter=1)
        gcmd = self._start(unit)
        self._refused(unit, gcmd, self._bus_refusal("Bambu_AMS_1", "0.5"))

    def test_externally_powered_dryer_does_not_block(self):
        # The configuration proven to hold on hardware: one unit on the bus,
        # one on its own 24V, both heating, no reset.
        unit, _sib, _p = self._bus({0: 23.8}, starter=1)
        self._started(unit, self._start(unit))

    def test_adapter_added_mid_cycle_unblocks_without_stopping(self):
        # Plug 24V into the unit that is already running: its next telemetry
        # line reads ~24, and the gate reads the latest value.
        unit, sib, _p = self._bus({0: 0.5}, starter=1)
        refused = self._start(unit)
        self._refused(unit, refused, self._bus_refusal("Bambu_AMS_1", "0.5"))
        unit._bridge._chmb_by_unit[0]["ad_v"] = 23.8
        self._started(unit, self._start(unit))
        assert sib[0]._drying is True

    def test_stopped_unit_does_not_block(self):
        # Stopped and gone quiet: its last line was minutes ago and the
        # telemetry streams only while a cycle runs, so the silence IS the
        # stop.
        unit, _sib, _p = self._bus({0: 0.5}, starter=1, drying=False,
                                   seen=1000.0, now=1200.0)
        self._started(unit, self._start(unit))

    def test_drying_but_silent_is_refused_not_assumed_safe(self):
        # A unit in the first ~10s of a cycle has not said how it is powered.
        unit, _sib, _p = self._bus({0: None}, starter=1)
        self._refused(unit, self._start(unit),
                      self._silent_refusal("Bambu_AMS_1"))

    def test_stale_reading_is_not_knowledge(self):
        # 23.8V from two minutes ago cannot rule out an adapter pulled since.
        unit, _sib, _p = self._bus({0: 23.8}, starter=1, seen=1000.0,
                                   now=1120.0)
        self._refused(unit, self._start(unit),
                      self._silent_refusal("Bambu_AMS_1"))

    def test_force_overrides(self):
        unit, _sib, _p = self._bus({0: 0.5}, starter=1)
        self._started(unit, self._start(unit, FORCE=1))

    def test_config_can_disable_it(self):
        unit, _sib, _p = self._bus({0: 0.5}, starter=1,
                                   starter_values={"dry_bus_interlock": False})
        assert unit.dry_bus_interlock is False
        self._started(unit, self._start(unit))

    def test_an_ht_on_the_bus_never_blocks(self):
        # An AMS HT will not heat without its own mains cord, so it is never
        # the unit drawing off the bus wire, and it has no jack reading.
        unit, _sib, printer = self._bus({}, starter=1)
        make_bambu_unit("Bambu_AMS_HT_5", printer=printer, model="ht",
                        ams_index=4, bridge=unit._bridge, drying=True)
        self._started(unit, self._start(unit))

    def test_an_ht_starting_is_not_judged_by_the_bus(self):
        printer = make_printer(now=1000.0)
        bridge = FakeBridge(chmb={0: {"ad_v": 0.5, "seen": 1000.0,
                                      "temp": 40.0, "state": 2}})
        make_bambu_unit("Bambu_AMS_1", printer=printer, ams_index=0,
                        bridge=bridge, drying=True)
        ht = make_bambu_unit("Bambu_AMS_HT_5", printer=printer, model="ht",
                             ams_index=4, bridge=bridge)
        gcmd = self._start(ht)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT_5 drying at "
                            "55C for 480min (addr 0x1800, id 128).")]
        assert bridge.sent == [self.HT_FRAME]
        assert ht.logger.messages == []

    def test_a_heaterless_neighbour_is_not_judged(self):
        unit, _sib, printer = self._bus({}, starter=1)
        unit._bridge._chmb_by_unit[0] = {"ad_v": 0.5, "seen": 1000.0,
                                         "temp": 40.0, "state": 2}
        make_bambu_unit("Bambu_AMS_1", printer=printer, model="ams1",
                        ams_index=0, bridge=unit._bridge, drying=True)
        self._started(unit, self._start(unit))

    def test_a_unit_on_another_bridge_never_blocks(self):
        # Another bridge is another bus with another supply.
        unit, _sib, printer = self._bus({}, starter=1)
        far = FakeBridge(chmb={0: {"ad_v": 0.5, "seen": 1000.0, "temp": 40.0,
                                   "state": 2}})
        make_bambu_unit("Bambu_AMS_9", printer=printer, ams_index=0,
                        bridge=far, drying=True)
        self._started(unit, self._start(unit))
        assert far.sent == []

    def test_unclaimed_placeholder_never_blocks(self):
        # An unclaimed bay sits at chain index 0 and owns no chamber, so it
        # would read the real unit's telemetry as its own.
        unit, _sib, printer = self._bus({}, starter=1)
        unit._bridge._chmb_by_unit[0] = {"ad_v": 0.5, "seen": 1000.0,
                                         "temp": 40.0, "state": 2}
        ghost = make_bambu_unit("Bambu_AMS_ghost", printer=printer,
                                ams_index=0, bridge=unit._bridge,
                                drying=True, values={"pool": True})
        assert ghost.pool is True
        self._started(unit, self._start(unit))

    def test_third_unit_blocked_by_the_bus_powered_one_of_two(self):
        # One on its adapter, one on the bus: the refusal names the unit
        # that is actually spending the allowance.
        unit, _sib, _p = self._bus({0: 23.8, 1: 0.5}, starter=2)
        self._refused(unit, self._start(unit),
                      self._bus_refusal("Bambu_AMS_2", "0.5"))

    def test_all_externally_powered_never_block(self):
        unit, _sib, _p = self._bus({0: 23.8, 1: 23.7}, starter=2)
        gcmd = self._start(unit)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_3 drying at "
                            "55C for 480min (addr 0x0700, id 2).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 2, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x0700, "amsid": 2}]
        assert unit.logger.messages == []

    def test_fourth_may_start_off_the_bus_when_the_other_three_are_external(
            self):
        # Three adapters constrain nothing: the bus allowance is unspent.
        unit, _sib, _p = self._bus({0: 23.8, 1: 23.7, 2: 23.9}, starter=3)
        self._started(unit, self._start(unit))

    def test_fourth_is_refused_when_one_of_three_is_on_the_bus(self):
        unit, _sib, _p = self._bus({0: 23.8, 1: 0.5, 2: 23.9}, starter=3)
        self._refused(unit, self._start(unit),
                      self._bus_refusal("Bambu_AMS_2", "0.5"))

    def test_the_bus_unit_blocks_wherever_it_sits_in_the_chain(self):
        # The loop must not stop at the first externally powered unit, nor
        # depend on chain order.
        for i in range(3):
            volts: Dict[int, Optional[float]] = {0: 23.8, 1: 23.8, 2: 23.8}
            volts[i] = 0.5
            unit, _sib, _p = self._bus(volts, starter=3)
            self._refused(unit, self._start(unit),
                          self._bus_refusal(f"Bambu_AMS_{i + 1}", "0.5"))

    def test_one_silent_unit_among_three_still_blocks(self):
        unit, _sib, _p = self._bus({0: 23.8, 1: None, 2: 23.9}, starter=3)
        self._refused(unit, self._start(unit),
                      self._silent_refusal("Bambu_AMS_2"))

    def test_racing_starts_cannot_both_get_through(self):
        # Two starts inside one ~10s reporting interval: the first sets
        # _drying at once and has no reading yet, so the second is refused.
        unit, _sib, printer = self._bus({0: 23.8, 1: 23.9}, starter=3)
        first = make_bambu_unit("Bambu_AMS_3", printer=printer, ams_index=2,
                                bridge=unit._bridge)
        self._start(first)
        assert first._drying is True
        gcmd = self._start(unit)
        assert gcmd.messages == [(
            "respond_info",
            self.PREFIX + self._silent_refusal("Bambu_AMS_3"))]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 2, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x0700, "amsid": 2}]
        assert unit._drying is False
        assert unit.logger.messages == []

    def test_a_cycle_nobody_here_started_still_blocks(self):
        # `_drying` is adopted from telemetry inside get_status, so a cycle
        # the printer started reads False until something polls that unit.
        unit, sib, _p = self._bus({0: 0.5}, starter=1, drying=False)
        assert sib[0]._drying is False
        assert sib[0]._heating_now() is True
        self._refused(unit, self._start(unit),
                      self._bus_refusal("Bambu_AMS_1", "0.5"))

    def test_a_stopped_units_wind_down_line_is_not_a_running_cycle(self):
        # A stopping AMS emits another line or two, and STOP stamps
        # _dry_adopt_after past them, so stopping a unit does not block the
        # next start for the length of the grace.
        unit, sib, _p = self._bus({0: None}, starter=1, now=985.0)
        sib[0].gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_1")
        assert sib[0]._dry_adopt_after == 1010.0
        unit.reactor.now = 1000.0
        unit._bridge._chmb_by_unit[0] = {"ad_v": 0.5, "seen": 1000.0,
                                         "temp": 40.0, "state": 2}
        assert sib[0]._heating_now() is False
        gcmd = self._start(unit)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_2 drying at "
                            "55C for 480min (addr 0x0700, id 1).")]
        assert unit._bridge.sent == [
            {"cmd": "dry", "unit": 0, "on": 0, "addr": 0x0700, "amsid": 0},
            {"cmd": "dry", "unit": 1, "on": 1, "temp": 55, "time": 480,
             "rotate": 0, "addr": 0x0700, "amsid": 1}]
        assert unit.logger.messages == []

    def test_a_full_bus_of_adapters_never_blocks_anyone(self):
        # Four units, all on adapters: each may start while the other three
        # run. The interlock caps drying off the BUS, not drying.
        for starter in range(4):
            volts: Dict[int, Optional[float]] = {
                i: 23.8 for i in range(4) if i != starter}
            unit, _sib, _p = self._bus(volts, starter=starter)
            gcmd = self._start(unit)
            assert gcmd.messages == [(
                "respond_info",
                f"AFC_BAMBU_HEATER_START: Bambu_AMS_{starter + 1} drying at "
                f"55C for 480min (addr 0x0700, id {starter}).")]
            assert unit._drying is True
            assert unit.logger.messages == []

    # ── the command itself ────────────────────────────────────────────────

    def test_rotate_allowed_when_bay_only(self):
        unit = self._unit(lanes=[LaneSpec("lane5", 0)])
        gcmd = self._start(unit, ROTATE=1)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_2 drying at 55C "
                            "for 480min with spool rotation (addr 0x0700, id "
                            "1).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 1, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 1,
                                      "addr": 0x0700, "amsid": 1}]
        assert unit._drying is True
        assert unit._dry_rotate == 1
        assert unit.logger.messages == []

    def test_rotate_gated_when_lane_committed(self):
        unit = self._unit(lanes=[LaneSpec("lane5", 0, tool_loaded=True)])
        gcmd = self._start(unit, ROTATE=1)
        assert gcmd.messages == [
            self._rotate_off("Bambu_AMS_2", "lane5"),
            ("respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_2 drying at "
                             "55C for 480min (addr 0x0700, id 1).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 1, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x0700, "amsid": 1}]
        assert unit._dry_rotate == 0
        assert unit.logger.messages == []

    def test_temp_clamped_to_ceiling(self):
        unit = self._unit()
        gcmd = self._start(unit, TEMP=85, ROTATE=0)
        assert gcmd.messages == [
            ("respond_info", "AFC_BAMBU_HEATER_START: TEMP 85C exceeds "
                             "Bambu_AMS_2's drying max 65C -- clamping to "
                             "65C."),
            ("respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_2 drying at "
                             "65C for 480min (addr 0x0700, id 1).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 1, "on": 1,
                                      "temp": 65, "time": 480, "rotate": 0,
                                      "addr": 0x0700, "amsid": 1}]
        assert unit._dry_temp == 65
        assert unit.logger.messages == []

    def test_ht_ceiling_allows_85(self):
        unit = self._unit(model="ht", ams_index=2, name="Bambu_AMS_3")
        gcmd = self._start(unit, TEMP=85, ROTATE=0)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_3 drying at 85C "
                            "for 480min (addr 0x1800, id 2).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 2, "on": 1,
                                      "temp": 85, "time": 480, "rotate": 0,
                                      "addr": 0x1800, "amsid": 2}]
        assert unit.logger.messages == []

    def test_ht_addressing_sent(self):
        unit = self._unit(model="ht", ams_index=2, name="Bambu_AMS_3")
        gcmd = self._start(unit, ROTATE=0)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_3 drying at 55C "
                            "for 480min (addr 0x1800, id 2).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 2, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x1800, "amsid": 2}]
        assert unit._drying is True
        assert unit._dry_host_refusal == ""
        assert unit.logger.messages == []

    def test_ams2pro_addressing_default(self):
        unit = self._unit()
        self._started(unit, self._start(unit, ROTATE=0))

    def test_ht_ceiling_still_clamps_above_85(self):
        unit = self._unit(model="ht", ams_index=2, name="Bambu_AMS_3")
        gcmd = self._start(unit, TEMP=99, ROTATE=0)
        assert gcmd.messages == [
            ("respond_info", "AFC_BAMBU_HEATER_START: TEMP 99C exceeds "
                             "Bambu_AMS_3's drying max 85C -- clamping to "
                             "85C."),
            ("respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_3 drying at "
                             "85C for 480min (addr 0x1800, id 2).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 2, "on": 1,
                                      "temp": 85, "time": 480, "rotate": 0,
                                      "addr": 0x1800, "amsid": 2}]
        assert unit.logger.messages == []

    class _NoDryErrorBridge(FakeBridge):
        """A bridge module from before dry refusals were kept."""

        def clear_dry_error(self, unit: Optional[int]) -> None:
            """:raises AttributeError: it has no refusal to clear"""
            raise AttributeError("clear_dry_error")

    def test_a_bridge_that_keeps_no_refusal_still_starts(self):
        unit = make_bambu_unit("Bambu_AMS_2", printer=make_printer(now=1000.0),
                               ams_index=1, bridge=self._NoDryErrorBridge())
        self._started(unit, self._start(unit, ROTATE=0))

    def test_a_boxed_unit_given_a_heater_is_held_to_the_bus(self):
        # AFC_BridgeBox's "boxed" tag names no generation and has no model
        # profile; with heater: True it dries at 0x0700, so it is judged by
        # the bus like an AMS 2 Pro, not skipped like an HT.
        unit, _sib, _p = self._bus({0: 0.5}, starter=1, starter_values={
            "ams_model": "boxed", "heater": True})
        assert (unit.has_heater, unit.dry_dev_addr) == (True, 0x0700)
        gcmd = self._start(unit)
        self._refused(unit, gcmd, self._bus_refusal("Bambu_AMS_1", "0.5"))

    def test_ht_with_tool_loaded_lane_starts(self):
        # PRINT AND HEAT: AMS HT firmware 05.00.22.19 heats while printing,
        # so a lane at the toolhead is the normal way to start a cycle. A
        # refusal or a toolhead warning is what a regression looks like.
        unit = self._unit(model="ht", ams_index=4, name="Bambu_AMS_HT",
                          lanes=[LaneSpec("lane20", 0, tool_loaded=True)])
        gcmd = self._start(unit, ROTATE=0)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT drying at "
                            "55C for 480min (addr 0x1800, id 128).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 4, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x1800, "amsid": 128}]
        assert unit._drying is True
        assert unit._dry_host_refusal == ""
        assert unit.logger.messages == []

    def test_ht_with_nothing_loaded_starts(self):
        # HT-ness alone does not refuse.
        unit = self._unit(model="ht", ams_index=4, name="Bambu_AMS_HT",
                          lanes=[LaneSpec("lane20", 0)])
        gcmd = self._start(unit, ROTATE=0)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT drying at "
                            "55C for 480min (addr 0x1800, id 128).")]
        assert unit._bridge.sent == [self.HT_FRAME]
        assert unit._drying is True
        assert unit.logger.messages == []

    def test_boxed_unit_with_tool_loaded_lane_still_starts(self):
        # An AMS 2 dries while printing; only its rotation is gated.
        unit = self._unit(lanes=[LaneSpec("lane5", 0, tool_loaded=True)])
        self._started(unit, self._start(unit, ROTATE=0))

    def test_ignored_on_heaterless_unit(self):
        unit = self._unit(model="ams1", ams_index=0, name="Bambu_AMS_1")
        gcmd = self._start(unit, ROTATE=0)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_1 has no drying "
                            "heater (heater: false). Only the AMS2 Pro can "
                            "dry -- ignoring.")]
        assert unit._bridge.sent == []                   # nothing sent
        assert unit._drying is False
        assert unit.logger.messages == []

    def test_start_clears_the_previous_cycles_evidence(self):
        bridge = FakeBridge(
            chmb={0: {"temp": 52.0, "target": 55.0, "state": 2,
                      "seen": 50.0}},
            status={"units": [{"n": 0, "online": True, "dryrem": 27313}]})
        unit = make_bambu_unit("Bambu_AMS_HT", printer=make_printer(now=10.0),
                               model="ht", bridge=bridge, drying=True)
        unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_HT")
        assert (unit._dry_adopt_after, unit._dryrem_at_stop) == (35.0, 27313)
        unit._dry_seen_live = True
        unit.reactor.now = 200.0
        gcmd = self._start(unit, ROTATE=0, AMSID=0, ADDR=0x1800)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT drying at "
                            "55C for 480min (addr 0x1800, id 0).")]
        assert unit._drying is True
        assert unit._dry_adopt_after == 200.0
        assert unit._dry_seen_live is False
        assert unit._dryrem_at_stop is None      # a new cycle retires the stamp
        assert unit._dry_started_at == 200.0
        assert unit._dry_minutes == 480
        assert unit.logger.messages == []

    def test_a_follower_on_a_lane_not_printing_is_stood_down(self):
        unit = self._unit(lanes=(LaneSpec("lane5", 1),))
        unit._following_lane = unit.lanes["lane5"]
        gcmd = self._start(unit)
        assert unit._following_lane is None
        assert unit._bridge.sent == [
            {"cmd": "assist", "unit": 1, "slot": 1, "on": False},
            {"cmd": "dry", "unit": 1, "on": 1, "temp": 55, "time": 480,
             "rotate": 0, "addr": 0x0700, "amsid": 1}]
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_2 drying at "
                            "55C for 480min (addr 0x0700, id 1).")]
        assert unit.logger.messages == []

    def test_an_addressing_override_needs_force(self):
        # A mismatch on either half would target another unit's heater.
        for params, shown in (({"AMSID": 2}, "2/0x0700"),
                              ({"ADDR": 0x1800}, "1/0x1800")):
            unit = self._unit()
            unit._dryrem_at_stop = 27313
            gcmd = FakeGcmd(dict(UNIT="Bambu_AMS_2", TEMP=55, TIME=480,
                                 **params))
            with pytest.raises(BambuPrinter.command_error) as exc:
                unit.cmd_AFC_BAMBU_HEATER_START(gcmd)
            assert str(exc.value) == (
                f"AFC_BAMBU_HEATER_START: AMSID/ADDR override ({shown}) does "
                f"not match Bambu_AMS_2's own addressing (1/0x0700), another "
                f"unit's heater would be targeted. Drop the override, or add "
                f"FORCE=1 for deliberate diagnostics.")
            assert gcmd.messages == []
            assert unit._bridge.sent == []
            assert unit.logger.messages == []
            # Refused before anything changed: not drying, stop stamp kept.
            assert unit._drying is False
            assert unit.get_status(0)["drying"] is False
            assert unit._dryrem_at_stop == 27313
        unit = self._unit()
        gcmd = self._start(unit, AMSID=2, FORCE=1)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_2 drying at "
                            "55C for 480min (addr 0x0700, id 2).")]
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 1, "on": 1,
                                      "temp": 55, "time": 480, "rotate": 0,
                                      "addr": 0x0700, "amsid": 2}]
        assert unit.logger.messages == []

    def test_a_unit_the_bus_does_not_answer_for_is_refused(self):
        bridge = FakeBridge(online=[True, False])
        unit = make_bambu_unit("Bambu_AMS_2", printer=make_printer(),
                               ams_index=1, bridge=bridge)
        unit._dryrem_at_stop = 27313
        gcmd = FakeGcmd({"UNIT": "Bambu_AMS_2", "TEMP": 55, "TIME": 480})
        with pytest.raises(BambuPrinter.command_error) as exc:
            unit.cmd_AFC_BAMBU_HEATER_START(gcmd)
        assert str(exc.value) == (
            "AFC_BAMBU_HEATER_START: Bambu_AMS_2 is not online -- nothing on "
            "the bus is answering for it, so the heater command would go "
            "nowhere. Check the unit is powered and chained, then retry.")
        assert gcmd.messages == []
        assert bridge.sent == []
        assert unit.logger.messages == []
        # Refused before anything changed: not drying, stop stamp kept.
        assert unit._drying is False
        assert unit.get_status(0)["drying"] is False
        assert unit._dryrem_at_stop == 27313

    def test_no_bridge_is_refused(self):
        unit = make_bambu_unit("Bambu_AMS_2", ams_index=1, offline=True)
        with pytest.raises(BambuPrinter.command_error) as exc:
            self._start(unit)
        assert str(exc.value) == (
            "AFC_BAMBU_HEATER_START: bridge not connected for Bambu_AMS_2")
        assert unit.logger.messages == []

    def test_a_hub_STAGED_lane_starts_too(self):
        # loaded_to_hub is a staging state this module sets and clears
        # itself, with the filament still inside the unit.
        unit = self._unit(model="ht", ams_index=4, name="Bambu_AMS_HT",
                          lanes=[LaneSpec("lane20", 0, loaded_to_hub=True)])
        gcmd = self._start(unit, ROTATE=0)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT drying at "
                            "55C for 480min (addr 0x1800, id 128).")]
        assert unit._bridge.sent == [self.HT_FRAME]
        assert unit._drying is True
        assert unit.logger.messages == []

    def test_rotate_gating_still_uses_committed_lanes(self):
        # The unit will not turn a spool with filament in its feeder, and
        # loaded_to_hub is exactly that state on a Bambu lane.
        unit = self._unit(model="ht", ams_index=4, name="Bambu_AMS_HT",
                          lanes=[LaneSpec("lane20", 0, loaded_to_hub=True)])
        gcmd = self._start(unit, ROTATE=1)
        assert gcmd.messages == [
            self._rotate_off("Bambu_AMS_HT", "lane20"),
            ("respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT drying at "
                             "55C for 480min (addr 0x1800, id 128).")]
        assert unit._bridge.sent == [self.HT_FRAME]
        assert unit.logger.messages == []

    def test_an_empty_unit_still_gets_its_rotation(self):
        # The HT with nothing in the feeder: the flag goes out.
        unit = self._unit(model="ht", ams_index=4, name="Bambu_AMS_HT",
                          lanes=[LaneSpec("lane20", 0)])
        gcmd = self._start(unit, ROTATE=1)
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_START: Bambu_AMS_HT drying at "
                            "55C for 480min with spool rotation (addr 0x1800, "
                            "id 128).")]
        assert unit._bridge.sent == [dict(self.HT_FRAME, rotate=1)]
        assert unit.logger.messages == []


class TestAfcBambuAMSCmdAFCBambuHeaterStop:
    STOPPED = ("respond_info",
               "AFC_BAMBU_HEATER_STOP: Bambu_AMS_HT drying stopped.")

    @staticmethod
    def _ht(ams_index: int = 0, now: float = 200.0,
            bridge: Optional[FakeBridge] = None) -> afcBambuAMS:
        """
        :param ams_index: the HT's chain index
        :param now: the clock
        :param bridge: its bridge; a quiet one when None
        :return afcBambuAMS: an AMS HT that is drying
        """
        return make_bambu_unit("Bambu_AMS_HT", printer=make_printer(now=now),
                               model="ht", ams_index=ams_index,
                               bridge=bridge, drying=True)

    def test_stop_carries_ht_addressing(self):
        unit = self._ht(ams_index=2)
        gcmd = unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_HT")
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 2, "on": 0,
                                      "addr": 0x1800,       # HT hears the stop
                                      "amsid": 2}]
        assert unit._drying is False
        assert gcmd.messages == [self.STOPPED]
        assert unit.logger.messages == []

    def test_stop_clears_the_host_refusal(self):
        unit = self._ht(ams_index=4)
        unit._dry_host_refusal = "stale reason"
        gcmd = unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_HT")
        assert unit._dry_host_refusal == ""
        assert unit._bridge.sent == [{"cmd": "dry", "unit": 4, "on": 0,
                                      "addr": 0x1800, "amsid": 128}]
        assert unit._drying is False
        assert gcmd.messages == [self.STOPPED]
        assert unit.logger.messages == []

    def test_stop_stamps_the_transition(self):
        bridge = FakeBridge(chmb={0: {"temp": 52.0, "target": 55.0,
                                      "state": 2, "seen": 170.0}})
        unit = self._ht(bridge=bridge)
        unit._dry_seen_live = True
        unit._dry_started_at, unit._dry_minutes = 150.0, 480
        gcmd = unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_HT")
        assert unit._drying is False
        # Stamped forward by the grace: an AMS keeps narrating for a moment
        # after being told to stop, and those lines must not re-adopt the
        # cycle -- that is why Stop had to be pressed twice on hardware.
        assert unit._dry_adopt_after == 225.0
        assert unit._dry_seen_live is False
        assert (unit._dry_started_at, unit._dry_minutes) == (None, 0)
        assert bridge.sent == [{"cmd": "dry", "unit": 0, "on": 0,
                                "addr": 0x1800, "amsid": 0}]
        assert unit._dryrem_at_stop is None     # nothing reported a countdown
        assert gcmd.messages == [self.STOPPED]
        assert unit.logger.messages == []

    def test_stop_stamps_the_countdown_it_is_stopping(self):
        bridge = FakeBridge(status={"units": [
            {"n": 0, "online": True, "dryrem": 27313},
            {"n": 4, "online": True, "dryrem": 28000}]})
        unit = self._ht(bridge=bridge)
        gcmd = unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_HT")
        assert unit._dryrem_at_stop == 27313      # ours, not the other HT's
        assert bridge.sent == [{"cmd": "dry", "unit": 0, "on": 0,
                                "addr": 0x1800, "amsid": 0}]
        assert unit._drying is False
        assert unit._dry_adopt_after == 225.0
        assert gcmd.messages == [self.STOPPED]
        assert unit.logger.messages == []

    def test_a_status_that_cannot_be_read_stamps_no_countdown(self):
        bridge = FakeBridge(raising={"latest_status": OSError("port closed")})
        unit = self._ht(bridge=bridge)
        gcmd = unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_HT")
        assert unit._dryrem_at_stop is None
        assert unit._drying is False
        assert bridge.sent == [{"cmd": "dry", "unit": 0, "on": 0,
                                "addr": 0x1800, "amsid": 0}]
        assert gcmd.messages == [self.STOPPED]
        assert unit.logger.messages == []

    def test_a_heaterless_unit_has_nothing_to_stop(self):
        unit = make_bambu_unit(model="ams1")
        gcmd = unit.gcode.run("AFC_BAMBU_HEATER_STOP", UNIT="Bambu_AMS_1")
        assert gcmd.messages == [(
            "respond_info", "AFC_BAMBU_HEATER_STOP: Bambu_AMS_1 has no drying "
                            "heater (heater: false) -- nothing to stop.")]
        assert unit._bridge.sent == []
        assert unit.logger.messages == []


class TestAfcBambuAMSCmdAFCBambuSniff:
    """
    AFC_BAMBU_SNIFF: hands the bus to the printer, or takes it back. Sniff
    mode makes the bridge transmit nothing, so the failure guarded here is a
    bridge that silently stops driving.
    """

    LISTEN = ("AFC_BAMBU_SNIFF: Bambu_AMS_1 bridge going listen-only. It will "
              "NOT drive its AMS units until ON=0 (or a reboot). Captured "
              "frames go to AFC.log as SNIFF lines.")
    DRIVE = "AFC_BAMBU_SNIFF: Bambu_AMS_1 bridge back to driving the bus."

    @staticmethod
    def _unit(printing: bool = False) -> afcBambuAMS:
        """
        :param printing: a print is running
        :return afcBambuAMS: the unit
        """
        printer = make_printer()
        if printing:
            printer.set_print_state("printing")
        return make_bambu_unit(printer=printer)

    @staticmethod
    def _sniff(unit: afcBambuAMS, **params: Any) -> FakeGcmd:
        """
        :param unit: the unit
        :return FakeGcmd: AFC_BAMBU_SNIFF UNIT=<unit> with ``params``
        """
        return unit.gcode.run("AFC_BAMBU_SNIFF", UNIT=unit.name, **params)

    def test_on_sends_the_command(self):
        unit = self._unit()
        gcmd = self._sniff(unit, ON=1)
        assert unit._bridge.sent == [{"cmd": "sniff", "on": 1}]
        assert gcmd.messages == [("respond_info", self.LISTEN)]
        assert unit.logger.messages == []

    def test_off_sends_the_command(self):
        unit = self._unit()
        gcmd = self._sniff(unit, ON=0)
        assert unit._bridge.sent == [{"cmd": "sniff", "on": 0}]
        assert gcmd.messages == [("respond_info", self.DRIVE)]
        assert unit.logger.messages == []

    def test_defaults_to_on(self):
        unit = self._unit()
        gcmd = self._sniff(unit)
        assert unit._bridge.sent == [{"cmd": "sniff", "on": 1}]
        assert gcmd.messages == [("respond_info", self.LISTEN)]
        assert unit.logger.messages == []

    def test_refuses_to_start_sniffing_mid_print(self):
        unit = self._unit(printing=True)
        with pytest.raises(BambuPrinter.command_error) as exc:
            self._sniff(unit, ON=1)
        assert str(exc.value) == (
            "AFC_BAMBU_SNIFF: refusing to sniff on Bambu_AMS_1 while a print "
            "is running -- sniff mode transmits nothing, so every load and "
            "unload on this bridge would go nowhere.")
        assert unit._bridge.sent == []          # nothing reached the bridge
        assert unit.logger.messages == []

    def test_stopping_sniff_is_allowed_mid_print(self):
        # ON=0 is the recovery from having sniffed, and must never be gated
        # behind the state it repairs.
        unit = self._unit(printing=True)
        gcmd = self._sniff(unit, ON=0)
        assert unit._bridge.sent == [{"cmd": "sniff", "on": 0}]
        assert gcmd.messages == [("respond_info", self.DRIVE)]
        assert unit.logger.messages == []

    def test_no_bridge_errors(self):
        unit = make_bambu_unit(offline=True)
        with pytest.raises(BambuPrinter.command_error) as exc:
            self._sniff(unit, ON=1)
        assert str(exc.value) == (
            "AFC_BAMBU_SNIFF: bridge not connected for Bambu_AMS_1")
        assert unit.logger.messages == []


class TestAfcBambuAMSReportUids:
    def test_report_uids_lists_with_occupancy(self):
        bridge = FakeBridge(uids=["AAA", "BBB"], status={"slots": [
            {"unit": 0, "i": 0, "present": True, "material": "PLA Basic"},
            {"unit": 1, "i": 0, "present": False, "material": None}]})
