    # ── a reconnect between an insert and its read ─────────────────────────

    @pytest.mark.parametrize("insert", ["blank", "reread-owed", "ht-blank"])
    def test_a_link_drop_between_a_mid_print_insert_and_its_read_keeps_the_read(
            self, monkeypatch, insert):
        # The link drops and comes back after lane15 went on defaults and
        # before the unit read the new reel. The reconnect forgets the
        # link's presence history, but this process's removal edge still
        # cleared the lane: the boot hold must not keep the read off it.
        ht = insert == "ht-blank"
        slot = 0 if ht else 3
        client = _p2_flap_spoolman()
        unit = _p2_flap_unit(monkeypatch, ht=ht, client=client)
        lane = unit.lanes["lane15"]
        _p2_flap_feed(unit, _p2_flap_gone(ht=ht), dt=1.0, times=3)
        frame = (_p2_flap_frame(True, ht=ht, rrq=1)
                 if insert == "reread-owed"
                 else _p2_flap_frame(True, ht=ht, tagged=False))
        _p2_flap_feed(unit, frame, dt=1.0, times=8)
        assert self._profile(lane) == self.DEFAULTS
        assert unit.logger.messages == [
            _p2_flap_removed(slot), _p2_flap_unbinding(),
            _p2_flap_inserted(slot), self._unread(slot)]
        unit.logger.messages.clear()
        unit._on_bridge_reconnect()
        _p2_flap_feed(unit, frame, dt=1.0, times=3)
        _p2_flap_feed(unit, self._new_reel(ht), dt=1.0, times=10)
        assert unit.logger.messages == self._petg_read(slot)
        assert client.searches == 1
        assert (lane.spool_id, lane.material, lane.color) == (200, "PETG",
                                                              "#FF0000")
        assert [o["cmd"] for o in unit._bridge.sent] == (
            _p2_flap_reconnect_cmds(ht))

    def test_a_pico_reboot_after_a_mid_print_swap_puts_no_lane_on_defaults(
            self, monkeypatch):
        # What the removal edge leaves behind outlives the link only for the
        # boot hold. The swapped reel was read and linked; then the Pico
        # reboots mid-print, reports the bay empty and brings it back blank
        # until the record is read again. No new spool went in.
        client = _p2_flap_spoolman()
        unit = _p2_flap_unit(monkeypatch, client=client)
        lane = unit.lanes["lane15"]
        _p2_flap_feed(unit, _p2_flap_gone(), dt=1.0, times=3)
        _p2_flap_feed(unit, _p2_flap_frame(True, tagged=False), dt=1.0,
                      times=3)
        _p2_flap_feed(unit, self._new_reel(), dt=1.0, times=5)
        assert lane.spool_id == 200
        assert unit.logger.messages == [
            _p2_flap_removed(), _p2_flap_unbinding(), _p2_flap_inserted(),
            self._unread()] + self._petg_read()
        unit.logger.messages.clear()
        unit._on_bridge_reconnect()
        _p2_flap_feed(unit, _p2_flap_gone())
        _p2_flap_feed(unit, _p2_flap_frame(True, tagged=False), dt=1.0,
                      times=5)
        # Only the swap's own line said "nothing has read it".
        assert unit.logger.messages == [
            _p2_flap_removed(), _p2_flap_unbinding(200), _p2_flap_inserted()]
        unit.logger.messages.clear()
        # The counters restarted with the Pico.
        _p2_flap_feed(unit, self._new_reel(sseq=0, sres=0, mseq=0, mpct=0),
                      dt=1.0, times=5)
        assert (lane.spool_id, lane.material) == (200, "PETG")
        assert unit.logger.messages == [
            ("info", f"{_P2_FLAP}: applied tag to lane15: Bambu PETG Basic "
                     f"#FF0000"),
            ("debug", f"{_P2_FLAP}: lane15 tag -- PETG Basic GFG00 | color "
                      f"#FF0000 | uid AABBCCDD | remaining no measurement yet "
                      f"| nominal 1000 g | nozzle 230-260C | bed 70C "
                      f"(material)"),
            ("debug", f"{_P2_FLAP}: matched lane15 to Spoolman spool 200 by "
                      f"tray UID {_P2_TRAY_NEW}")]
        assert client.searches == 2

    # ── Spoolman answering late ────────────────────────────────────────────

    class _DownSpoolman(_P2FlapSpoolman):
        """Spoolman not answering: every search fails, reachable() is False."""

        def search_spools(self) -> List[Dict[str, Any]]:
            """:raises ConnectionError: always, counting the search"""
            self.searches += 1
            raise ConnectionError("Spoolman did not answer")

    @staticmethod
    def _run_jobs(unit: afcBambuAMS, jobs: "queue.Queue[Any]") -> None:
        """The delegate's queued Spoolman jobs, run now, and their answers."""
        while not jobs.empty():
            jobs.get_nowait()()
            unit.reactor.run_callbacks()

    @pytest.mark.parametrize("meanwhile", ["flap", "out-and-back", "emptied"])
    def test_a_late_unanswered_lookup_leaves_no_retry_behind(
            self, monkeypatch, meanwhile):
        # With Spoolman timing out, a restored lane's lookup comes back up to
        # 20 s later, and the bay can change in between. A "no answer" about
        # a spool that has left must not re-arm a retry for an empty bay, nor
        # leave one nothing would send behind the bay's own lookup.
        jobs: "queue.Queue[Any]" = queue.Queue()
        # The shared worker's queue, with no thread draining it.
        monkeypatch.setattr(BambuSpoolman, "_spool_q", jobs)
        client = self._DownSpoolman(reachable=False)
        unit = _p2_flap_unit(monkeypatch, client=client, inline=False,
                             values={"auto_scan": False})
        lane = unit.lanes["lane15"]
        self._printing(unit, False)
        lane.spool_id = None                       # restored with no spool
        _p2_flap_feed(unit, _p2_flap_frame(True), dt=1.0)
        assert jobs.qsize() == 1 and unit._spoolman_latched == {3}
        looking = ("debug", f"{_P2_FLAP}: lane15 has no Spoolman spool and its "
                            f"bay's tag 95F2C30C (PLA Basic) matches the lane "
                            f"-- looking the tag up in Spoolman; the lane is "
                            f"left as AFC restored it")
        assert unit.logger.messages == [looking]
        unit.logger.messages.clear()
        rec: Dict[str, Any] = {}
        if meanwhile == "flap":
            _p2_flap_feed(unit, _p2_flap_frame(False))
            _p2_flap_feed(unit, _p2_flap_frame(True))
        else:
            _p2_flap_feed(unit, _p2_flap_gone(), dt=1.0, times=2)
        if meanwhile == "out-and-back":
            _p2_flap_feed(unit, _p2_flap_frame(True, tagged=False, rrq=1),
                          dt=1.0, times=2)
            rec = {"sseq": 1, "sres": 1}
            _p2_flap_feed(unit, _p2_flap_frame(True, **rec), dt=1.0, times=3)
        jobs.get_nowait()()                        # the restart lookup
        unit.reactor.run_callbacks()
        assert client.searches == 1
        if meanwhile == "emptied":
            assert unit._lookup_retry == {} and unit._spoolman_latched == set()
            assert unit.logger.messages == [_p2_flap_removed()]
            return
        assert unit.logger.messages == [
            _p2_flap_removed(), _p2_flap_inserted(),
            ("info", f"{_P2_FLAP}: applied tag to lane15: Bambu PLA Basic "
                     f"#0086D6"),
            ("debug", f"{_P2_FLAP}: lane15 tag -- PLA Basic GFA00 | color "
                      f"#0086D6 | uid 95F2C30C | remaining no measurement yet "
                      f"| nominal 1000 g | nozzle 190-230C | bed 55C "
                      f"(material)"),
            ("debug", f"{_P2_FLAP}: Spoolman did not answer the lookup of "
                      f"95F2C30C for lane15; asking again in 30 s")]
        unit.logger.messages.clear()
        for _ in range(5):
            _p2_flap_feed(unit, _p2_flap_frame(True, **rec), dt=1.0)
            self._run_jobs(unit, jobs)
        # The bay's own lookup took over, and no retry is left behind it.
        assert unit._lookup_retry == {} and client.searches == 2
        unit.reactor.now += 120.0
        for _ in range(5):
            _p2_flap_feed(unit, _p2_flap_frame(True, **rec), dt=1.0)
            self._run_jobs(unit, jobs)
        assert client.searches == 2                # nothing left to ask
        assert unit.logger.messages == []
        unit._cap_open_pending(3, asked=True)
        for _ in range(3):
            _p2_flap_feed(unit, _p2_flap_frame(True, mseq=5, mpct=74, **rec),
                          dt=1.0)
            self._run_jobs(unit, jobs)
        how = "tag read" if meanwhile == "out-and-back" else "tag on file"
        assert unit.logger.messages == [
            self._capsample(3, "None", "PLA Basic", 1.24, 74, 608),
            ("info", f"Bambu_AMS_1 lane15: {how}: PLA Basic (0086D6) [tag "
                     f"95F2C30C]. Measured about 74% left -- roughly 608 g of "
                     f"a 1000 g spool; not linked to a Spoolman spool, so "
                     f"this is kept on the lane only -- Spoolman has no spool "
                     f"carrying 95F2C30C and auto-create is off for this unit "
                     f"(add 'auto_spoolman_create: True' to [AFC_BambuAMS "
                     f"Bambu_AMS_1], or bind that UID to an existing "
                     f"spool).")]

    # ── a link that lands after the bay emptied ────────────────────────────

    class _FetchingSpool(FakeAfcSpool):
        """
        AFC core's spool object from before on_done: it binds when its fetch
        lands and says nothing.
        """

        def __init__(self) -> None:
            """Start with nothing fetched."""
            super().__init__()
            self.pending: List[Tuple[Any, Any]] = []

        def set_spoolID(self, lane: Any, spool_id: Any, *args: Any,
                        **kwargs: Any) -> None:
            """Record the call; the fetch lands with land()."""
            super().set_spoolID(lane, spool_id, *args, **kwargs)
            self.pending.append((lane, spool_id))

        def land(self, stored: float) -> None:
            """:param stored: Spoolman's remaining weight for the spool"""
            for lane, spool_id in self.pending:
                lane.spool_id, lane.weight = spool_id, stored
            self.pending = []

    def test_a_lane_put_on_defaults_drops_a_link_that_landed_after_its_removal(
            self, monkeypatch):
        # A relink sent before a real removal can bind the lane of the
        # emptied bay unseen. A reel put in during the print goes on lane
        # defaults linked to nothing, not to the spool that left.
        unit = _p2_flap_unit(monkeypatch)
        lane = unit.lanes["lane15"]
        unit.afc.spool = self._FetchingSpool()
        _p2_flap_feed(unit, _p2_flap_frame(False))
        _p2_flap_feed(unit, _p2_flap_frame(True))
        assert unit.afc.spool.calls == [("set_spoolID", (lane, 136), {})]
        _p2_flap_feed(unit, _p2_flap_gone())
        unit.afc.spool.land(670.8)
        assert lane.spool_id == 136
        unit.logger.messages.clear()
        _p2_flap_feed(unit, _p2_flap_frame(True, tagged=False), dt=1.0,
                      times=8)
        assert lane.spool_id == ""
        assert self._profile(lane) == self.DEFAULTS
        assert unit.logger.messages == [
            _p2_flap_inserted(),
            ("debug", f"{_P2_FLAP}: unbinding lane15 from spool 136 -- nothing "
                      f"has read the spool in the bay, so this link is the "
                      f"previous spool's"),
            self._unread()]

    # ── an insert held while a lane is at the toolhead ─────────────────────

    HELD = ("info", f"{_P2_FLAP}: spool in slot 3 -- lane15 goes on lane "
                    f"defaults until it is read, and the SCAN is held: a lane "
                    f"on this unit is loaded to the toolhead and a scan would "
                    f"move filament on it. It scans itself when that lane "
                    f"comes out, or run AFC_BAMBU_SCAN LANE=lane15 whenever "
                    f"you like")

    def _held_unit(self, monkeypatch: pytest.MonkeyPatch) -> afcBambuAMS:
        """
        :param monkeypatch: pytest's monkeypatch fixture
        :return afcBambuAMS: the flap unit idle, with lane12 on bay 1 loaded
          to the toolhead (no pull-in), after lane15's spool came out
        """
        unit = _p2_flap_unit(monkeypatch, toolhead=True,
                             values={"insert_pullin": False})
        self._printing(unit, False)
        _p2_flap_feed(unit, self._answered(_p2_flap_gone()), dt=1.0, times=3)
        lane = unit.lanes["lane15"]
        assert (lane.material, lane.spool_id) == ("", "")
        assert unit.logger.messages == [_p2_flap_removed(),
                                        _p2_flap_unbinding()]
        unit.logger.messages.clear()
        return unit

    @pytest.mark.parametrize("seen_leave", [True, False],
                             ids=["removal-seen", "empty-since-before-restart"])
    def test_an_insert_held_for_the_toolhead_goes_on_defaults(
            self, monkeypatch, seen_leave):
        # Printer 2, 23:39:04: lane4 at the toolhead, an untagged reel into
        # lane6's bay, empty since before the last restart. The line said
        # "applied lane defaults" and the lane stayed blank.
        unit = self._held_unit(monkeypatch)
        lane = unit.lanes["lane15"]
        if not seen_leave:
            unit._on_bridge_reconnect()
            _p2_flap_feed(unit, self._answered(_p2_flap_gone()), dt=1.0,
                          times=3)
            assert 3 not in unit._removed_bays
            # The settle re-asserts the toolhead lane; no removal is said.
            assert unit.logger.messages == [
                ("debug", f"{_P2_FLAP}: lane12 loaded at startup, "
                          f"re-asserting AMS loaded state + follower")]
            unit.logger.messages.clear()
        saves = unit.afc.save_vars.call_count
        sent = len(unit._bridge.sent)
        _p2_flap_feed(unit, self._answered(_p2_flap_frame(True, tagged=False)),
                      dt=1.0, times=6)
        assert self._profile(lane) == self.DEFAULTS
        assert lane.spool_id == ""
        assert unit.afc.save_vars.call_count == saves + 1   # the defaults
        assert unit._bridge.sent[sent:] == []               # no scan
        # The held insert's own line already said how to have it read.
        assert unit.logger.messages == [_p2_flap_inserted(), self.HELD]

    def test_an_insert_held_for_the_toolhead_scans_when_the_lane_comes_out(
            self, monkeypatch):
        # On the first connection after a boot: the HELD line promises a scan
        # once the toolhead lane comes out.
        unit = self._held_unit(monkeypatch)
        insert = self._answered(_p2_flap_frame(True, tagged=False))
        _p2_flap_feed(unit, insert, dt=1.0, times=6)
        assert unit._scan_defer == [False, False, False, True]
        assert unit._auto_scanned[3] is True
        assert unit.logger.messages == [_p2_flap_inserted(), self.HELD]
        unit.logger.messages.clear()
        unit.lanes["lane12"].tool_loaded = False   # the toolhead lane is out
        _p2_flap_feed(unit, insert, dt=1.0, times=3)
        assert unit._bridge.sent == [
            {"cmd": "capscan", "trig": 1, "ins": 1, "unit": 0, "slot": 3}]
        assert unit._scan_defer == [False, False, False, False]
        assert unit.logger.messages == [
            ("info", "AFC bambu Bambu_AMS_1: unit is free -- scanning the spool "
                     "in slot 3 that was held back"),
            ("debug", "AFC bambu Bambu_AMS_1: new spool detected in slot 3, "
                      "scanning tag"),
            ("debug", "AFC bambu Bambu_AMS_1: slot 3 scan verdict -> waiting (fw "
                      "seq=0 res=0 | record: mat=- uid=- present=True)")]

