    # ── what a frame meets on the way: a held scan, a missing memo, a
    #    collaborator that fails ────────────────────────────────────────────

    def test_a_held_insert_is_kept_for_replay_once_a_reset_built_the_lists(
            self, monkeypatch):
        # Pins _maybe_auto_scan's memo rebuild; kept here for this part's coverage.
        # The replay lists exist only once a disconnect's reset has built
        # them; the defaults memos are rebuilt where a unit lacks them.
        unit = self._held_unit(monkeypatch)
        unit._scan_defer = [False] * 4
        unit._untagged_rearmed = [False, False, False, True]
        unit._defaults_due = None
        unit._defaults_quiet = None
        insert = self._answered(_p2_flap_frame(True, tagged=False))
        _p2_flap_feed(unit, insert, dt=1.0)
        inserted_at = unit.reactor.now
        assert unit._scan_defer == [False, False, False, True]
        assert unit._defaults_due == {3: inserted_at + 2.0}
        assert unit._defaults_quiet == {3}
        assert unit.logger.messages == [_p2_flap_inserted(), self.HELD]
        unit.logger.messages.clear()
        # lane12 is still at the toolhead: the scan stays held.
        _p2_flap_feed(unit, insert, dt=0.5)
        assert unit._scan_defer == [False, False, False, True]
        assert unit._bridge.sent == []
        assert unit.logger.messages == []
        # The spool comes out before its defaults: nothing is left to
        # replay, and the next spool is a new question.
        _p2_flap_feed(unit, self._answered(_p2_flap_gone()), dt=0.5)
        assert unit._scan_defer == [False] * 4
        assert unit._untagged_rearmed == [False] * 4
        assert unit.logger.messages == [_p2_flap_removed()]

    def test_a_mid_print_insert_rebuilds_a_missing_defaults_memo(
            self, monkeypatch):
        # Pins _maybe_auto_scan's memo rebuild; kept here for this part's coverage.
        unit = _p2_flap_unit(monkeypatch)
        _p2_flap_feed(unit, self._answered(_p2_flap_gone()), dt=1.0)
        unit.logger.messages.clear()
        unit._defaults_due = None
        _p2_flap_feed(unit, self._answered(_p2_flap_frame(True, tagged=False)),
                      dt=1.0)
        assert unit._defaults_due == {3: unit.reactor.now + 2.0}
        assert unit.logger.messages == [_p2_flap_inserted()]

    def test_presence_memos_a_unit_lacks_are_rebuilt_on_its_edges(
            self, monkeypatch):
        # Pins a branch of _maybe_auto_scan and _scan_in_flight; kept here for this part's coverage.
        unit = _p2_flap_unit(monkeypatch)
        for memo in ("_present_seen", "_removed_bays", "_cleared_bays",
                     "_meas_departed", "_scan_motion_t0"):
            setattr(unit, memo, None)
        _p2_flap_feed(unit, _p2_flap_frame(True), dt=1.0)
        assert unit._present_seen == {3}
