        _p2_flap_feed(unit, _p2_flap_gone(mseq=5, mpct=60), dt=1.0)
        assert unit._removed_bays == {3} and unit._cleared_bays == {3}
        assert unit._meas_departed == {3: (5, 60)}
        assert unit.lanes["lane15"].spool_id == ""
        assert unit.logger.messages == [_p2_flap_removed(),
                                        _p2_flap_unbinding(),
                                        self._departed(60, 5)]

