    # ── only this unit's bays, only once its identity is known ─────────────

    @staticmethod
    def _plain(monkeypatch: pytest.MonkeyPatch, *, ams_index: int = 0,
               uid: Optional[str] = None,
               resolved: bool = True) -> afcBambuAMS:
        """
        :param monkeypatch: pytest's monkeypatch fixture
        :param ams_index: its chain index
        :param uid: its unit_uid
        :param resolved: that UID is resolved to the index
        :return afcBambuAMS: an AMS 2 "AMS" with no lanes, its bays unknown
        """
        printer = make_printer(monkeypatch=monkeypatch)
        unit = make_bambu_unit(
            "AMS", printer=printer, ams_index=ams_index,
            values={"unit_uid": uid} if uid else {}, id_resolved=resolved,
            bridge=FakeBridge(uids=[uid] if uid else []))
        unit.logger.messages.clear()
        return unit

    def test_keeps_only_our_units_slots(self, monkeypatch):
        unit = self._plain(monkeypatch, ams_index=1)
        unit._on_status({"slots": [
            {"unit": 0, "i": 0, "present": True, "material": "PLA"},
            {"unit": 1, "i": 0, "present": True, "material": "PETG"},
            {"unit": 1, "i": 2, "present": False}]})
        assert unit._slots[0]["material"] == "PETG"    # unit 1 bay 1 kept
        assert unit._slots[2]["present"] is False      # unit 1 bay 3 kept
        assert unit._slots[1] == {} and unit._slots[3] == {}  # unit 0 ignored
        assert unit.logger.messages == []

    def test_untagged_slot_defaults_unit_0(self, monkeypatch):
        unit = self._plain(monkeypatch)
        unit._on_status({"slots": [{"i": 0, "present": True,
                                    "material": "PLA"}]})
        assert unit._slots[0]["material"] == "PLA"
        assert unit.logger.messages == []

    def test_a_slot_index_out_of_range_is_dropped(self, monkeypatch):
        unit = self._plain(monkeypatch)
        unit._on_status({"slots": [{"i": 4, "present": True},
                                   {"i": -1, "present": True}]})
        assert unit._slots == [{}, {}, {}, {}]
        assert unit.logger.messages == []

    FRAME = {"slots": [{"unit": 0, "i": 0, "present": True,
                        "material": "PLA"}]}

    def test_unresolved_uid_applies_nothing(self, monkeypatch):
        # Until the chain map resolves the UID, every unit on the bus would
        # match unit 0's bays: one HT tag landed on three lanes at once.
        unit = self._plain(monkeypatch, uid="AAAA00", resolved=False)
        unit._on_status(self.FRAME)
        assert unit._slots == [{}, {}, {}, {}]
        assert unit._presence_ok is False
        assert unit.logger.messages == []

    def test_resolved_uid_applies_normally(self, monkeypatch):
        unit = self._plain(monkeypatch, uid="AAAA00", resolved=True)
        unit._on_status(self.FRAME)
        assert unit._slots[0]["material"] == "PLA"
        assert unit._presence_ok is True
        assert unit.logger.messages == []

