    @pytest.mark.parametrize("owned", [True, False],
                             ids=["claimed-at-prep", "boot-hold"])
    @pytest.mark.parametrize("record", ["read", "profile-blanked"])
    def test_a_capscan_on_a_lane_on_defaults_says_no_lookup_was_made(
            self, monkeypatch, record, owned):
        # lane15 restored on defaults: no record can be tested against it,
        # so nothing is looked up, and a capscan's summary is said at once
        # without claiming a lookup.
        unit = self._lane15(monkeypatch, owned=owned, colour="")
